INSERT INTO system_vocabulary_words (id, set_id, topic_id, part_id, word, ipa, cefr, part_of_speech, meaning_vi, definition_en, example_en, example_vi, example_toeic, audio_us, audio_uk, image_url, synonyms, antonyms, phrases, confusables, word_family, audio_voices, note_vi, toeic_topic, difficulty_level, order_index) VALUES
('1c5a4d86-f08a-5b28-aecb-721e69cdf743', '306b49d3-4d3a-5fda-97a7-d5790b808339', '17bc21e4-5e91-5a10-b376-d0b3020efdab', '73886620-44f0-5907-990b-548f14480bbc', 'go backpacking', '/ɡəʊ bækˌpækɪŋ/', 'A2', 'phrase', 'Đi du lịch tự túc, thường mang theo ba lô và ít hành lý.', 'to travel carrying your clothes and other things in a pack on your back.', 'They decided to go backpacking across Southeast Asia for a month.', 'Họ quyết định đi du lịch bụi khắp Đông Nam Á trong một tháng.', '{\"en\": \"Many young professionals choose to go backpacking during their annual career break.\", \"vi\": \"Nhiều chuyên gia trẻ chọn đi du lịch bụi trong kỳ nghỉ phép hàng năm của họ.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/go-backpacking-ljspeech-04f73f45.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/go-backpacking-cori-04f73f45.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/go-backpacking-3b14959e.webp', NULL, NULL, '[{\"phrase\": \"go backpacking trip\", \"meaning\": \"chuyến đi du lịch bụi\"}, {\"phrase\": \"go backpacking alone\", \"meaning\": \"đi du lịch bụi một mình\"}]', '[{\"word\": \"hiking\", \"note_vi\": \"đi bộ đường dài trong thiên nhiên, thường ngắn ngày hơn\"}]', '[{\"pos\": \"noun\", \"word\": \"backpacker\"}, {\"pos\": \"noun\", \"word\": \"backpack\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/go-backpacking-cori-04f73f45.mp3\", \"/storage/v1/object/public/pronunciation/v2/go-backpacking-aru0-04f73f45.mp3\", \"/storage/v1/object/public/pronunciation/v2/go-backpacking-aru5-04f73f45.mp3\", \"/storage/v1/object/public/pronunciation/v2/go-backpacking-aru6-04f73f45.mp3\", \"/storage/v1/object/public/pronunciation/v2/go-backpacking-aru10-04f73f45.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/go-backpacking-aru9-04f73f45.mp3\", \"/storage/v1/object/public/pronunciation/v2/go-backpacking-aru3-04f73f45.mp3\", \"/storage/v1/object/public/pronunciation/v2/go-backpacking-aru7-04f73f45.mp3\", \"/storage/v1/object/public/pronunciation/v2/go-backpacking-aru8-04f73f45.mp3\", \"/storage/v1/object/public/pronunciation/v2/go-backpacking-aru2-04f73f45.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/go-backpacking-ljspeech-04f73f45.mp3\", \"/storage/v1/object/public/pronunciation/v2/go-backpacking-lt408-04f73f45.mp3\", \"/storage/v1/object/public/pronunciation/v2/go-backpacking-lt138-04f73f45.mp3\", \"/storage/v1/object/public/pronunciation/v2/go-backpacking-lt624-04f73f45.mp3\", \"/storage/v1/object/public/pronunciation/v2/go-backpacking-lt396-04f73f45.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/go-backpacking-lt498-04f73f45.mp3\", \"/storage/v1/object/public/pronunciation/v2/go-backpacking-lt132-04f73f45.mp3\", \"/storage/v1/object/public/pronunciation/v2/go-backpacking-lt288-04f73f45.mp3\", \"/storage/v1/object/public/pronunciation/v2/go-backpacking-lt42-04f73f45.mp3\", \"/storage/v1/object/public/pronunciation/v2/go-backpacking-lt90-04f73f45.mp3\"]}}', 'Cụm từ này chỉ việc đi du lịch giá rẻ, tự túc với một chiếc ba lô lớn.', 'travel', 1, 0),
('98bdef57-60c1-5aa4-aa75-e2bcf9d3f76f', '306b49d3-4d3a-5fda-97a7-d5790b808339', '17bc21e4-5e91-5a10-b376-d0b3020efdab', '73886620-44f0-5907-990b-548f14480bbc', 'smartphone', '/ˈsmɑːt.fəʊn/', 'A2', 'noun', 'Điện thoại di động có nhiều chức năng như máy tính nhỏ.', 'An advanced cellular device featuring internet connectivity and various downloadable applications.', 'He uses his smartphone to check emails, browse the internet, and make calls.', 'Anh ấy dùng điện thoại thông minh của mình để kiểm tra email, lướt internet và gọi điện.', '{\"en\": \"Employees can access the company database directly from their smartphone during business trips.\", \"vi\": \"Nhân viên có thể truy cập cơ sở dữ liệu của công ty trực tiếp từ điện thoại thông minh của họ trong các chuyến công tác.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/smartphone-ljspeech-b520dff5.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/smartphone-cori-b520dff5.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/smartphone-70c7031a.webp', '[\"mobile phone\", \"cellphone\"]', NULL, '[{\"phrase\": \"smartphone application\", \"meaning\": \"ứng dụng điện thoại thông minh\"}, {\"phrase\": \"use a smartphone\", \"meaning\": \"sử dụng điện thoại thông minh\"}]', '[{\"word\": \"telephone\", \"note_vi\": \"telephone thường chỉ điện thoại bàn truyền thống\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/smartphone-cori-b520dff5.mp3\", \"/storage/v1/object/public/pronunciation/v2/smartphone-aru0-b520dff5.mp3\", \"/storage/v1/object/public/pronunciation/v2/smartphone-aru5-b520dff5.mp3\", \"/storage/v1/object/public/pronunciation/v2/smartphone-aru6-b520dff5.mp3\", \"/storage/v1/object/public/pronunciation/v2/smartphone-aru10-b520dff5.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/smartphone-aru9-b520dff5.mp3\", \"/storage/v1/object/public/pronunciation/v2/smartphone-aru3-b520dff5.mp3\", \"/storage/v1/object/public/pronunciation/v2/smartphone-aru7-b520dff5.mp3\", \"/storage/v1/object/public/pronunciation/v2/smartphone-aru8-b520dff5.mp3\", \"/storage/v1/object/public/pronunciation/v2/smartphone-aru2-b520dff5.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/smartphone-ljspeech-b520dff5.mp3\", \"/storage/v1/object/public/pronunciation/v2/smartphone-lt408-b520dff5.mp3\", \"/storage/v1/object/public/pronunciation/v2/smartphone-lt138-b520dff5.mp3\", \"/storage/v1/object/public/pronunciation/v2/smartphone-lt624-b520dff5.mp3\", \"/storage/v1/object/public/pronunciation/v2/smartphone-lt396-b520dff5.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/smartphone-lt498-b520dff5.mp3\", \"/storage/v1/object/public/pronunciation/v2/smartphone-lt132-b520dff5.mp3\", \"/storage/v1/object/public/pronunciation/v2/smartphone-lt288-b520dff5.mp3\", \"/storage/v1/object/public/pronunciation/v2/smartphone-lt42-b520dff5.mp3\", \"/storage/v1/object/public/pronunciation/v2/smartphone-lt90-b520dff5.mp3\"]}}', 'Từ ghép viết liền, không có khoảng cách ở giữa.', 'technology', 1, 1),
('e651a618-650e-5308-854d-2c55d5a26fde', '306b49d3-4d3a-5fda-97a7-d5790b808339', '17bc21e4-5e91-5a10-b376-d0b3020efdab', '73886620-44f0-5907-990b-548f14480bbc', 'tired', '/taɪəd/', 'A1', 'adjective', 'Cảm thấy cần được nghỉ ngơi, kiệt sức.', 'feeling that you need to rest or sleep because of hard work or activity.', 'After working all day, he felt very tired and just wanted to sleep.', 'Sau khi làm việc cả ngày, anh ấy cảm thấy rất mệt mỏi và chỉ muốn ngủ.', '{\"en\": \"The tired employees requested an extra break after working overtime on the new marketing campaign.\", \"vi\": \"Nhân viên mệt mỏi đã yêu cầu thêm giờ nghỉ sau khi làm thêm giờ cho chiến dịch tiếp thị mới.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/tired-ljspeech-511e9911.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/tired-cori-511e9911.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/tired-783f73ee.webp', '[\"exhausted\", \"weary\"]', '[\"energetic\", \"refreshed\"]', '[{\"phrase\": \"feel tired\", \"meaning\": \"cảm thấy mệt mỏi\"}, {\"phrase\": \"tired of\", \"meaning\": \"chán nản với điều gì\"}]', '[{\"word\": \"tiring\", \"note_vi\": \"tiring là tính từ chỉ nguyên nhân gây mệt, tired chỉ cảm giác của người.\"}]', '[{\"pos\": \"verb\", \"word\": \"tire\"}, {\"pos\": \"noun\", \"word\": \"tiredness\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/tired-cori-511e9911.mp3\", \"/storage/v1/object/public/pronunciation/v2/tired-aru0-511e9911.mp3\", \"/storage/v1/object/public/pronunciation/v2/tired-aru5-511e9911.mp3\", \"/storage/v1/object/public/pronunciation/v2/tired-aru6-511e9911.mp3\", \"/storage/v1/object/public/pronunciation/v2/tired-aru10-511e9911.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/tired-aru9-511e9911.mp3\", \"/storage/v1/object/public/pronunciation/v2/tired-aru3-511e9911.mp3\", \"/storage/v1/object/public/pronunciation/v2/tired-aru7-511e9911.mp3\", \"/storage/v1/object/public/pronunciation/v2/tired-aru8-511e9911.mp3\", \"/storage/v1/object/public/pronunciation/v2/tired-aru2-511e9911.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/tired-ljspeech-511e9911.mp3\", \"/storage/v1/object/public/pronunciation/v2/tired-lt408-511e9911.mp3\", \"/storage/v1/object/public/pronunciation/v2/tired-lt138-511e9911.mp3\", \"/storage/v1/object/public/pronunciation/v2/tired-lt624-511e9911.mp3\", \"/storage/v1/object/public/pronunciation/v2/tired-lt396-511e9911.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/tired-lt498-511e9911.mp3\", \"/storage/v1/object/public/pronunciation/v2/tired-lt132-511e9911.mp3\", \"/storage/v1/object/public/pronunciation/v2/tired-lt288-511e9911.mp3\", \"/storage/v1/object/public/pronunciation/v2/tired-lt42-511e9911.mp3\", \"/storage/v1/object/public/pronunciation/v2/tired-lt90-511e9911.mp3\"]}}', 'cần phân biệt tired (cảm giác) và tiring (gây ra sự mệt mỏi).', 'office', 1, 2),
('bf611ca1-c8d6-5e1c-b61e-28d5b56d055c', '306b49d3-4d3a-5fda-97a7-d5790b808339', '17bc21e4-5e91-5a10-b376-d0b3020efdab', '73886620-44f0-5907-990b-548f14480bbc', 'curly', '/ˈkɜːli/', 'A2', 'adjective', 'Có dạng xoăn, uốn lượn (thường nói về tóc).', 'having a shape that forms curved lines or small round rings instead of being straight.', 'She has beautiful curly hair that always looks great.', 'Cô ấy có mái tóc xoăn tuyệt đẹp trông lúc nào cũng rất ổn.', '{\"en\": \"The candidate with curly hair presented an innovative marketing plan to the interview panel.\", \"vi\": \"Ứng viên có mái tóc xoăn đã trình bày một kế hoạch tiếp thị sáng tạo trước hội đồng phỏng vấn.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/curly-ljspeech-e122d28c.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/curly-cori-e122d28c.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/curly-b9f11d0e.webp', '[\"wavy\", \"kinky\"]', '[\"straight\"]', '[{\"phrase\": \"curly hair\", \"meaning\": \"tóc xoăn\"}, {\"phrase\": \"naturally curly\", \"meaning\": \"xoăn tự nhiên\"}]', '[{\"word\": \"wavy\", \"note_vi\": \"wavy là tóc gợn sóng nhẹ, còn curly là xoăn thành lọn.\"}]', '[{\"pos\": \"noun\", \"word\": \"curl\"}, {\"pos\": \"verb\", \"word\": \"curl\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/curly-cori-e122d28c.mp3\", \"/storage/v1/object/public/pronunciation/v2/curly-aru0-e122d28c.mp3\", \"/storage/v1/object/public/pronunciation/v2/curly-aru5-e122d28c.mp3\", \"/storage/v1/object/public/pronunciation/v2/curly-aru6-e122d28c.mp3\", \"/storage/v1/object/public/pronunciation/v2/curly-aru10-e122d28c.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/curly-aru9-e122d28c.mp3\", \"/storage/v1/object/public/pronunciation/v2/curly-aru3-e122d28c.mp3\", \"/storage/v1/object/public/pronunciation/v2/curly-aru7-e122d28c.mp3\", \"/storage/v1/object/public/pronunciation/v2/curly-aru8-e122d28c.mp3\", \"/storage/v1/object/public/pronunciation/v2/curly-aru2-e122d28c.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/curly-ljspeech-e122d28c.mp3\", \"/storage/v1/object/public/pronunciation/v2/curly-lt408-e122d28c.mp3\", \"/storage/v1/object/public/pronunciation/v2/curly-lt138-e122d28c.mp3\", \"/storage/v1/object/public/pronunciation/v2/curly-lt624-e122d28c.mp3\", \"/storage/v1/object/public/pronunciation/v2/curly-lt396-e122d28c.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/curly-lt498-e122d28c.mp3\", \"/storage/v1/object/public/pronunciation/v2/curly-lt132-e122d28c.mp3\", \"/storage/v1/object/public/pronunciation/v2/curly-lt288-e122d28c.mp3\", \"/storage/v1/object/public/pronunciation/v2/curly-lt42-e122d28c.mp3\", \"/storage/v1/object/public/pronunciation/v2/curly-lt90-e122d28c.mp3\"]}}', 'Dùng để tả tóc xoăn hoặc hình dáng uốn cong.', 'daily', 1, 3),
('16baaceb-ed39-5071-b5f8-a2a60082c741', '306b49d3-4d3a-5fda-97a7-d5790b808339', '17bc21e4-5e91-5a10-b376-d0b3020efdab', '73886620-44f0-5907-990b-548f14480bbc', 'hold on', '/həʊld ɒn/', 'A2', 'phrasal verb', 'Chờ một chút (thường khi gọi điện thoại).', 'to wait for a short time, especially on the phone.', 'Please hold on for a moment while I transfer your call.', 'Xin vui lòng giữ máy một lát trong khi tôi chuyển cuộc gọi của bạn.', '{\"en\": \"Customer service asked me to hold on while they checked.\", \"vi\": \"Bộ phận chăm sóc khách hàng yêu cầu tôi giữ máy trong lúc họ kiểm tra.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/hold-on-ljspeech-a9822009.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/hold-on-cori-a9822009.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/hold-on-1c961fd1.webp', '[\"wait\", \"stay\"]', '[\"hang up\"]', '[{\"phrase\": \"hold on tight\", \"meaning\": \"bám chặt\"}, {\"phrase\": \"hold on a second\", \"meaning\": \"đợi một giây\"}, {\"phrase\": \"hold on the line\", \"meaning\": \"giữ máy điện thoại\"}]', '[{\"word\": \"hold up\", \"note_vi\": \"hold up là trì hoãn hoặc cướp, hold on là đợi\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/hold-on-cori-a9822009.mp3\", \"/storage/v1/object/public/pronunciation/v2/hold-on-aru0-a9822009.mp3\", \"/storage/v1/object/public/pronunciation/v2/hold-on-aru5-a9822009.mp3\", \"/storage/v1/object/public/pronunciation/v2/hold-on-aru6-a9822009.mp3\", \"/storage/v1/object/public/pronunciation/v2/hold-on-aru10-a9822009.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/hold-on-aru9-a9822009.mp3\", \"/storage/v1/object/public/pronunciation/v2/hold-on-aru3-a9822009.mp3\", \"/storage/v1/object/public/pronunciation/v2/hold-on-aru7-a9822009.mp3\", \"/storage/v1/object/public/pronunciation/v2/hold-on-aru8-a9822009.mp3\", \"/storage/v1/object/public/pronunciation/v2/hold-on-aru2-a9822009.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/hold-on-ljspeech-a9822009.mp3\", \"/storage/v1/object/public/pronunciation/v2/hold-on-lt408-a9822009.mp3\", \"/storage/v1/object/public/pronunciation/v2/hold-on-lt138-a9822009.mp3\", \"/storage/v1/object/public/pronunciation/v2/hold-on-lt624-a9822009.mp3\", \"/storage/v1/object/public/pronunciation/v2/hold-on-lt396-a9822009.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/hold-on-lt498-a9822009.mp3\", \"/storage/v1/object/public/pronunciation/v2/hold-on-lt132-a9822009.mp3\", \"/storage/v1/object/public/pronunciation/v2/hold-on-lt288-a9822009.mp3\", \"/storage/v1/object/public/pronunciation/v2/hold-on-lt42-a9822009.mp3\", \"/storage/v1/object/public/pronunciation/v2/hold-on-lt90-a9822009.mp3\"]}}', 'Trong điện thoại, hold on nghĩa là giữ máy, không phải cầm nắm.', 'office', 1, 4),
('7287a830-55d7-50db-8467-5e5a87da9e3a', '306b49d3-4d3a-5fda-97a7-d5790b808339', '17bc21e4-5e91-5a10-b376-d0b3020efdab', '73886620-44f0-5907-990b-548f14480bbc', 'lecture', 'UK: /ˈlɛktʃə/ | US: /ˈlɛktʃər/', 'B1', 'noun', 'bài giảng', 'an educational talk given to an audience, especially to students in a university setting.', 'The professor gave an interesting lecture on economics.', 'Giáo sư đã có một bài giảng thú vị về kinh tế học.', '{\"en\": \"Dr. Aris will deliver a lecture on corporate governance at tomorrow\'s seminar.\", \"vi\": \"Tiến sĩ Aris sẽ trình bày bài giảng về quản trị doanh nghiệp tại hội thảo ngày mai.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/lecture-ljspeech-af09e2fc.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/lecture-cori-af09e2fc.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/lecture-0387dee8.webp', '[\"presentation\", \"talk\", \"address\", \"speech\"]', NULL, '[{\"phrase\": \"give a lecture\", \"meaning\": \"thuyết giảng / cho bài giảng\"}, {\"phrase\": \"attend a lecture\", \"meaning\": \"tham dự bài giảng\"}]', '[{\"word\": \"lecturer\", \"note_vi\": \"lecturer chỉ người giảng dạy (giảng viên), trong khi lecture chỉ bài giảng\"}]', '[{\"pos\": \"verb\", \"word\": \"lecture\"}, {\"pos\": \"noun\", \"word\": \"lecturer\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/lecture-cori-af09e2fc.mp3\", \"/storage/v1/object/public/pronunciation/v2/lecture-aru0-af09e2fc.mp3\", \"/storage/v1/object/public/pronunciation/v2/lecture-aru5-af09e2fc.mp3\", \"/storage/v1/object/public/pronunciation/v2/lecture-aru6-af09e2fc.mp3\", \"/storage/v1/object/public/pronunciation/v2/lecture-aru10-af09e2fc.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/lecture-aru9-af09e2fc.mp3\", \"/storage/v1/object/public/pronunciation/v2/lecture-aru3-af09e2fc.mp3\", \"/storage/v1/object/public/pronunciation/v2/lecture-aru7-af09e2fc.mp3\", \"/storage/v1/object/public/pronunciation/v2/