('b643caa6-53fe-5e79-a17e-a9239de36ce5', '306b49d3-4d3a-5fda-97a7-d5790b808339', '17bc21e4-5e91-5a10-b376-d0b3020efdab', '73886620-44f0-5907-990b-548f14480bbc', 'whenever', 'UK: /wɛnˈɛvər/ | US: /wɛnˈɛvər/', 'B1', 'adverb', 'bất cứ khi nào', 'at any time or every time that something happens or is needed.', 'Call me whenever you need help.', 'Hãy gọi cho tôi bất cứ khi nào bạn cần giúp đỡ.', '{\"en\": \"You may access your online employee account whenever you need to check your pay stubs.\", \"vi\": \"Bạn có thể truy cập tài khoản nhân viên trực tuyến của mình bất cứ khi nào bạn cần kiểm tra phiếu lương.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/whenever-ljspeech-5b914347.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/whenever-cori-5b914347.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/whenever-8802eba9.webp', '[\"anytime\", \"every time that\"]', NULL, '[{\"phrase\": \"whenever possible\", \"meaning\": \"bất cứ khi nào có thể\"}, {\"phrase\": \"whenever convenient\", \"meaning\": \"bất cứ khi nào tiện\"}]', '[{\"word\": \"ever\", \"note_vi\": \"Ever là \'đã từng / bao giờ\', còn whenever chỉ thời điểm linh hoạt \'bất cứ khi nào\'.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/whenever-cori-5b914347.mp3\", \"/storage/v1/object/public/pronunciation/v2/whenever-aru0-5b914347.mp3\", \"/storage/v1/object/public/pronunciation/v2/whenever-aru5-5b914347.mp3\", \"/storage/v1/object/public/pronunciation/v2/whenever-aru6-5b914347.mp3\", \"/storage/v1/object/public/pronunciation/v2/whenever-aru10-5b914347.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/whenever-aru9-5b914347.mp3\", \"/storage/v1/object/public/pronunciation/v2/whenever-aru3-5b914347.mp3\", \"/storage/v1/object/public/pronunciation/v2/whenever-aru7-5b914347.mp3\", \"/storage/v1/object/public/pronunciation/v2/whenever-aru8-5b914347.mp3\", \"/storage/v1/object/public/pronunciation/v2/whenever-aru2-5b914347.mp3\