('d86ca711-3734-598c-a089-a82ef2283686', '306b49d3-4d3a-5fda-97a7-d5790b808339', '17bc21e4-5e91-5a10-b376-d0b3020efdab', '73886620-44f0-5907-990b-548f14480bbc', 'rugby', '/ˈrʌɡbi/', 'A2', 'noun', 'một môn thể thao đồng đội dùng bóng hình bầu dục.', 'a sport played by two teams with an oval ball that can be kicked or carried.', 'The company sponsored a local rugby tournament to promote employee fitness.', 'Công ty đã tài trợ một giải đấu bóng bầu dục địa phương nhằm nâng cao sức khỏe nhân viên.', '{\"en\": \"The company sponsored a local rugby match to increase its brand visibility.\", \"vi\": \"Công ty đã tài trợ một trận đấu bóng bầu dục địa phương để tăng độ nhận diện thương hiệu.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/rugby-ljspeech-68208df6.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/rugby-cori-68208df6.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/rugby-4a0c25b0.webp', NULL, NULL, '[{\"phrase\": \"rugby match\", \"meaning\": \"trận đấu bóng bầu dục\"}, {\"phrase\": \"play rugby\", \"meaning\": \"chơi bóng bầu dục\"}]', '[{\"word\": \"American football\", \"note_vi\": \"American football cho phép chuyền bóng về phía trước, rugby thì không\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/rugby-cori-68208df6.mp3\", \"/storage/v1/object/public/pronunciation/v2/rugby-aru0-68208df6.mp3\", \"/storage/v1/object/public/pronunciation/v2/rugby-aru5-68208df6.mp3\", \"/storage/v1/object/public/pronunciation/v2/rugby-aru6-68208df6.mp3\", \"/storage/v1/object/public/pronunciation/v2/rugby-aru10-68208df6.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/rugby-aru9-68208df6.mp3\", \"/storage/v1/object/public/pronunciation/v2/rugby-aru3-68208df6.mp3\", \"/storage/v1/object/public/pronunciation/v2/rugby-aru7-68208df6.mp3\", \"/storage/v1/object/public/pronunciation/v2/rugby-aru8-68208df6.mp3\", \"/storage/v1/object/public/pronunciation/v2/rugby-aru2-68208df6.mp3\"]}, \"us\":