('6bafca5c-8bae-5eed-8b1a-e255cdda2a7c', '306b49d3-4d3a-5fda-97a7-d5790b808339', '49a0f496-645a-5b44-94da-1264c7d8dbdb', '84b5e1b4-e6e0-5c15-88d9-0e751febd332', 'leaflet', '/ˈliːflət/', 'B1', 'noun', 'một tờ giấy nhỏ in thông tin quảng cáo hoặc tuyên truyền.', 'a small printed sheet of paper giving information or advertising something.', 'The charity handed out leaflets to raise awareness about their cause.', 'Tổ chức từ thiện đã phát tờ rơi để nâng cao nhận thức về mục đích của họ.', '{\"en\": \"Staff distributed a leaflet about the upcoming product launch to all office visitors.\", \"vi\": \"Nhân viên đã phát tờ rơi về buổi ra mắt sản phẩm sắp tới cho tất cả khách đến văn phòng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/leaflet-ljspeech-5f5555f4.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/leaflet-cori-5f5555f4.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/leaflet-158780df.webp', '[\"flyer\", \"brochure\", \"pamphlet\"]', NULL, '[{\"phrase\": \"hand out a leaflet\", \"meaning\": \"phát tờ rơi\"}, {\"phrase\": \"promotional leaflet\", \"meaning\": \"tờ rơi quảng cáo\"}, {\"phrase\": \"information leaflet\", \"meaning\": \"tờ rơi thông tin\"}]', '[{\"word\": \"brochure\", \"note_vi\": \"brochure thường nhiều trang hơn và in đẹp hơn leaflet\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/leaflet-cori-5f5555f4.mp3\", \"/storage/v1/object/public/pronunciation/v2/leaflet-aru0-5f5555f4.mp3\", \"/storage/v1/object/public/pronunciation/v2/leaflet-aru5-5f5555f4.mp3\", \"/storage/v1/object/public/pronunciation/v2/leaflet-aru6-5f5555f4.mp3\", \"/storage/v1/object/public/pronunciation/v2/leaflet-aru10-5f5555f4.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/leaflet-aru9-5f5555f4.mp3\", \"/storage/v1/object/public/pronunciation/v2/leaflet-aru3-5f5555f4.mp3\", \"/storage/v1/object/public/pronunciation/v2/leaflet-aru7-5f5555f4.mp3\", \"/storage/v1/object/public/pronunciation/