('d2b5e090-341f-581b-80ca-deab84faf356', '306b49d3-4d3a-5fda-97a7-d5790b808339', '65d9365f-51b8-5126-a5aa-7c25b22abc72', '27e9097a-97e5-5ba2-a361-99cbacde842f', 'vase', 'UK: /vɑːz/ | US: /veɪs/', 'B1', 'noun', 'bình hoa', 'an open decorative container usually made of glass or ceramic, used for flowers.', 'She placed fresh flowers in the vase.', 'Cô ấy đặt hoa tươi vào bình.', '{\"en\": \"A decorative glass vase with fresh flowers was placed in the middle of the conference table.\", \"vi\": \"Một bình hoa thủy tinh trang trí đựng hoa tươi đã được đặt ở giữa bàn họp.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/vase-ljspeech-28e4e605.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/vase-cori-28e4e605.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/vase-dce3c415.webp', '[\"urn\", \"jar\", \"container\"]', NULL, '[{\"phrase\": \"flower vase\", \"meaning\": \"bình cắm hoa\"}, {\"phrase\": \"ceramic vase\", \"meaning\": \"bình gốm\"}, {\"phrase\": \"place a vase\", \"meaning\": \"đặt một bình hoa\"}]', '[{\"word\": \"base\", \"note_vi\": \"\'vase\' (bình hoa) phát âm /veɪs/ hoặc /vɑːz/, khác với \'base\' /beɪs/ (chân đế/cơ sở).\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/vase-cori-28e4e605.mp3\", \"/storage/v1/object/public/pronunciation/v2/vase-aru0-28e4e605.mp3\", \"/storage/v1/object/public/pronunciation/v2/vase-aru5-28e4e605.mp3\", \"/storage/v1/object/public/pronunciation/v2/vase-aru6-28e4e605.mp3\", \"/storage/v1/object/public/pronunciation/v2/vase-aru10-28e4e605.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/vase-aru9-28e4e605.mp3\", \"/storage/v1/object/public/pronunciation/v2/vase-aru3-28e4e605.mp3\", \"/storage/v1/object/public/pronunciation/v2/vase-aru7-28e4e605.mp3\", \"/storage/v1/object/public/pronunciation/v2/vase-aru8-28e4e605.mp3\", \"/storage/v1/object/public/pronunciation/v2/vase-aru2-28e4e605.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronu