('72b2a717-505b-5296-9ca4-de847406c569', '306b49d3-4d3a-5fda-97a7-d5790b808339', 'b87d2bb8-ef71-511b-923b-6e1609bd1548', '7f8d6cb5-1f18-5d90-b1d7-5859d87a0ec3', 'store', 'UK: /stɔː/ | US: /stɔːr/', 'A2', 'noun', 'cửa hàng, tiệm', 'a retail establishment where goods and merchandise are sold directly to customers.', 'The new clothing store offers great discounts.', 'Cửa hàng quần áo mới có nhiều khuyến mãi lớn.', '{\"en\": \"The electronics store will offer a 20% discount during its anniversary sale.\", \"vi\": \"Cửa hàng điện máy sẽ giảm giá 20% trong dịp bán hàng kỷ niệm.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/store-ljspeech-3a21295d.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/store-cori-3a21295d.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/store-9010ae17.webp', '[\"shop\", \"outlet\", \"boutique\"]', NULL, '[{\"phrase\": \"retail store\", \"meaning\": \"cửa hàng bán lẻ\"}, {\"phrase\": \"department store\", \"meaning\": \"cửa hàng bách hóa\"}, {\"phrase\": \"chain store\", \"meaning\": \"chuỗi cửa hàng\"}]', '[{\"word\": \"story\", \"note_vi\": \"\'Story\' là câu chuyện hoặc tầng nhà (cách viết Anh-Mỹ), phát âm gần giống nhưng nghĩa hoàn toàn khác \'store\'.\"}]', '[{\"pos\": \"noun\", \"word\": \"storage\"}, {\"pos\": \"noun\", \"word\": \"storefront\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/store-cori-3a21295d.mp3\", \"/storage/v1/object/public/pronunciation/v2/store-aru0-3a21295d.mp3\", \"/storage/v1/object/public/pronunciation/v2/store-aru5-3a21295d.mp3\", \"/storage/v1/object/public/pronunciation/v2/store-aru6-3a21295d.mp3\", \"/storage/v1/object/public/pronunciation/v2/store-aru10-3a21295d.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/store-aru9-3a21295d.mp3\", \"/storage/v1/object/public/pronunciation/v2/store-aru3-3a21295d.mp3\", \"/storage/v1/object/public/pronunciation/v2/store-aru7-3a21295d.mp3\", \"/storage/v1/object/public/pronunciation/v2/s