('f5d7ff01-c1df-54a8-8525-9982b02d29aa', '306b49d3-4d3a-5fda-97a7-d5790b808339', 'ba4e89e9-ccbc-5ec1-8290-1d7189d2ee2a', '98359ed4-4c79-548e-9b36-170b56348c84', 'whoever', 'UK: /huːˈɛvə/ | US: /huˈɛvər/', 'B1', 'pronoun', 'bất cứ ai', 'any person who performs an action or meets a particular condition.', 'Whoever finishes first can leave early.', 'Bất cứ ai hoàn thành trước có thể về sớm.', '{\"en\": \"Whoever submits the highest bid before noon will win the procurement contract.\", \"vi\": \"Bất cứ ai nộp giá thầu cao nhất trước giữa trưa sẽ giành được hợp đồng thu mua.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/whoever-ljspeech-aa39520e.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/whoever-cori-aa39520e.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/whoever-019e2b31.webp', '[\"anyone who\", \"any person who\"]', NULL, '[{\"phrase\": \"whoever is responsible\", \"meaning\": \"bất kỳ ai chịu trách nhiệm\"}, {\"phrase\": \"whoever arrives first\", \"meaning\": \"bất cứ ai đến trước\"}]', '[{\"word\": \"whomever\", \"note_vi\": \"Whoever làm chủ ngữ trong mệnh đề, còn Whomever đóng vai trò tân ngữ (đối tượng chịu tác động).\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/whoever-cori-aa39520e.mp3\", \"/storage/v1/object/public/pronunciation/v2/whoever-aru0-aa39520e.mp3\", \"/storage/v1/object/public/pronunciation/v2/whoever-aru5-aa39520e.mp3\", \"/storage/v1/object/public/pronunciation/v2/whoever-aru6-aa39520e.mp3\", \"/storage/v1/object/public/pronunciation/v2/whoever-aru10-aa39520e.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/whoever-aru9-aa39520e.mp3\", \"/storage/v1/object/public/pronunciation/v2/whoever-aru3-aa39520e.mp3\", \"/storage/v1/object/public/pronunciation/v2/whoever-aru7-aa39520e.mp3\", \"/storage/v1/object/public/pronunciation/v2/whoever-aru8-aa39520e.mp3\", \"/storage/v1/object/public/pronunciation/v2/whoever-aru2-aa39520e.mp3\"]}, \"us\": {\"nu\":