('8248ed08-af21-52bd-b30b-026892e6206d', '306b49d3-4d3a-5fda-97a7-d5790b808339', 'ba4e89e9-ccbc-5ec1-8290-1d7189d2ee2a', '98359ed4-4c79-548e-9b36-170b56348c84', 'version', 'UK: /ˈvɜːʃn/ | US: /ˈvɜːrʒn/', 'B1', 'noun', 'phiên bản', 'a particular form or variation of something that differs from previous releases.', 'The latest version of the software has new features.', 'Phiên bản mới nhất của phần mềm có các tính năng mới.', '{\"en\": \"Please ensure you have downloaded the latest version of the employee handbook from the intranet.\", \"vi\": \"Vui lòng đảm bảo bạn đã tải phiên bản mới nhất của sổ tay nhân viên từ mạng nội bộ.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/version-ljspeech-c692273d.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/version-cori-c692273d.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/version-253bfdb2.webp', '[\"edition\", \"variant\", \"revision\", \"release\"]', NULL, '[{\"phrase\": \"latest version\", \"meaning\": \"phiên bản mới nhất\"}, {\"phrase\": \"updated version\", \"meaning\": \"phiên bản đã cập nhật\"}, {\"phrase\": \"draft version\", \"meaning\": \"bản thảo\"}]', NULL, NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/version-cori-c692273d.mp3\", \"/storage/v1/object/public/pronunciation/v2/version-aru0-c692273d.mp3\", \"/storage/v1/object/public/pronunciation/v2/version-aru5-c692273d.mp3\", \"/storage/v1/object/public/pronunciation/v2/version-aru6-c692273d.mp3\", \"/storage/v1/object/public/pronunciation/v2/version-aru10-c692273d.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/version-aru9-c692273d.mp3\", \"/storage/v1/object/public/pronunciation/v2/version-aru3-c692273d.mp3\", \"/storage/v1/object/public/pronunciation/v2/version-aru7-c692273d.mp3\", \"/storage/v1/object/public/pronunciation/v2/version-aru8-c692273d.mp3\", \"/storage/v1/object/public/pronunciation/v2/version-aru2-c692273d.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/p