('ea5d7232-e488-5f61-92a2-0fb4a22f8b99', '306b49d3-4d3a-5fda-97a7-d5790b808339', 'ba4e89e9-ccbc-5ec1-8290-1d7189d2ee2a', '98359ed4-4c79-548e-9b36-170b56348c84', 'injury', 'UK: /ˈɪndʒəri/ | US: /ˈɪndʒəri/', 'B1', 'noun', 'chấn thương, vết thương', 'physical damage or harm done to a person or animal\'s body.', 'He sustained a minor injury at work.', 'Anh ấy bị một chấn thương nhẹ tại nơi làm việc.', '{\"en\": \"To prevent workplace injury, all factory staff must wear protective gear at all times.\", \"vi\": \"Để ngăn ngừa chấn thương tại nơi làm việc, tất cả nhân viên nhà máy phải luôn đeo thiết bị bảo hộ.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/injury-ljspeech-c5b0c16a.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/injury-cori-c5b0c16a.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/injury-1ccf4880.webp', '[\"damage\", \"harm\", \"wound\", \"impairment\"]', NULL, '[{\"phrase\": \"workplace injury\", \"meaning\": \"chấn thương tại nơi làm việc\"}, {\"phrase\": \"minor injury\", \"meaning\": \"chấn thương nhẹ\"}, {\"phrase\": \"prevent injury\", \"meaning\": \"phòng tránh chấn thương\"}]', '[{\"word\": \"damage\", \"note_vi\": \"Hư hại tài sản/đồ vật, còn injury dùng cho chấn thương cơ thể con người\"}]', '[{\"pos\": \"verb\", \"word\": \"injure\"}, {\"pos\": \"adjective\", \"word\": \"injured\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/injury-cori-c5b0c16a.mp3\", \"/storage/v1/object/public/pronunciation/v2/injury-aru0-c5b0c16a.mp3\", \"/storage/v1/object/public/pronunciation/v2/injury-aru5-c5b0c16a.mp3\", \"/storage/v1/object/public/pronunciation/v2/injury-aru6-c5b0c16a.mp3\", \"/storage/v1/object/public/pronunciation/v2/injury-aru10-c5b0c16a.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/injury-aru9-c5b0c16a.mp3\", \"/storage/v1/object/public/pronunciation/v2/injury-aru3-c5b0c16a.mp3\", \"/storage/v1/object/public/pronunciation/v2/injury-aru7-c5b0c16a.mp3\", \"/sto