('c9e8cedb-890d-5d1a-ac37-e0bed3455bdc', '4b7cd0c9-3be0-5af8-9e5b-33c6dba6466a', '8725c478-984b-529a-b658-60921d5c44c6', '8b1f136e-8650-541c-9118-9da92e68e74b', 'aromatic', '/ˌærəˈmætɪk/', 'B1', 'adjective', 'Thơm, có mùi thơm dễ chịu.', 'having a pleasant and distinctive smell or fragrance.', 'The garden was filled with the aromatic scent of blooming roses.', 'Khu vườn tràn ngập mùi thơm dễ chịu của những bông hồng đang nở.', '{\"en\": \"The aromatic morning coffee welcomed guests at the hotel lobby.\", \"vi\": \"Ly cà phê thơm sáng sớm đã chào đón khách ở sảnh khách sạn.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/aromatic-ljspeech-100a97b6.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/aromatic-cori-100a97b6.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/aromatic-d7d74a9a.webp', '[\"fragrant\", \"scented\", \"perfumed\"]', '[\"smelly\", \"malodorous\"]', '[{\"phrase\": \"aromatic herbs\", \"meaning\": \"thảo mộc thơm\"}, {\"phrase\": \"aromatic coffee\", \"meaning\": \"cà phê thơm\"}, {\"phrase\": \"aromatic oil\", \"meaning\": \"tinh dầu thơm\"}]', '[{\"word\": \"atomic\", \"note_vi\": \"atomic nghĩa là nguyên tử, không phải thơm\"}]', '[{\"pos\": \"noun\", \"word\": \"aroma\"}, {\"pos\": \"adverb\", \"word\": \"aromatically\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/aromatic-cori-100a97b6.mp3\", \"/storage/v1/object/public/pronunciation/v2/aromatic-aru0-100a97b6.mp3\", \"/storage/v1/object/public/pronunciation/v2/aromatic-aru5-100a97b6.mp3\", \"/storage/v1/object/public/pronunciation/v2/aromatic-aru6-100a97b6.mp3\", \"/storage/v1/object/public/pronunciation/v2/aromatic-aru10-100a97b6.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/aromatic-aru9-100a97b6.mp3\", \"/storage/v1/object/public/pronunciation/v2/aromatic-aru3-100a97b6.mp3\", \"/storage/v1/object/public/pronunciation/v2/aromatic-aru7-100a97b6.mp3\", \"/storage/v1/object/public/pronunciation/v2/aromatic-ar