('7d33a754-5934-51da-ae93-69e1e8db7872', '4b7cd0c9-3be0-5af8-9e5b-33c6dba6466a', 'ca619a71-55d1-51b2-93e6-31bc29b4e194', '4ee7d933-a125-5828-8d55-5a5f6dd69ab3', 'stimulate', '/ˈstɪmjuleɪt/', 'B1', 'verb', 'Kích thích, khuyến khích một hoạt động hoặc quá trình.', 'to encourage or cause an activity to begin or increase.', 'Good teachers know how to stimulate students\' interest in learning.', 'Những giáo viên giỏi biết cách kích thích hứng thú học tập của học sinh.', '{\"en\": \"The bonus plan will stimulate staff to meet sales targets.\", \"vi\": \"Kế hoạch thưởng sẽ kích thích nhân viên đạt chỉ tiêu bán hàng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/stimulate-ljspeech-e26c861b.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/stimulate-cori-e26c861b.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/stimulate-06d06e2b.webp', '[\"encourage\", \"prompt\", \"activate\"]', '[\"discourage\", \"suppress\"]', '[{\"phrase\": \"stimulate growth\", \"meaning\": \"kích thích tăng trưởng\"}, {\"phrase\": \"stimulate demand\", \"meaning\": \"kích thích nhu cầu\"}, {\"phrase\": \"stimulate interest\", \"meaning\": \"kích thích sự quan tâm\"}]', '[{\"word\": \"simulate\", \"note_vi\": \"simulate nghĩa là mô phỏng, không phải kích thích\"}]', '[{\"pos\": \"noun\", \"word\": \"stimulation\"}, {\"pos\": \"adjective\", \"word\": \"stimulating\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/stimulate-cori-e26c861b.mp3\", \"/storage/v1/object/public/pronunciation/v2/stimulate-aru0-e26c861b.mp3\", \"/storage/v1/object/public/pronunciation/v2/stimulate-aru5-e26c861b.mp3\", \"/storage/v1/object/public/pronunciation/v2/stimulate-aru6-e26c861b.mp3\", \"/storage/v1/object/public/pronunciation/v2/stimulate-aru10-e26c861b.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/stimulate-aru9-e26c861b.mp3\", \"/storage/v1/object/public/pronunciation/v2/stimulate-aru3-e26c861b.mp3\", \"/storage/v1/object/public/pro