('d46a7c6e-f3ba-5216-9ac5-21216a4770d8', '916d709b-04e4-55ae-a9e0-a43b249586ee', '04d109ea-6f45-57ec-b456-cb7b7902f986', '9dacbe20-c457-584e-ad0d-585fc7cde270', 'noisy', 'UK: /ˈnɔɪzi/ | US: /ˈnɔɪzi/', 'A2', 'adjective', 'ồn ào', 'making or full of a lot of loud or unpleasant sounds.', 'The construction site was very noisy.', 'Công trường xây dựng rất ồn ào.', '{\"en\": \"Employees complained that the air conditioning unit was too noisy during meetings.\", \"vi\": \"Nhân viên phàn nàn rằng máy điều hòa quá ồn ào trong các cuộc họp.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/noisy-ljspeech-e570e577.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/noisy-cori-e570e577.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/noisy-7c052cd5.webp', '[\"loud\", \"boisterous\", \"rowdy\"]', '[\"quiet\", \"silent\", \"peaceful\"]', '[{\"phrase\": \"noisy environment\", \"meaning\": \"môi trường ồn ào\"}, {\"phrase\": \"noisy machinery\", \"meaning\": \"máy móc gây tiếng ồn\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"noise\"}, {\"pos\": \"adverb\", \"word\": \"noisily\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/noisy-cori-e570e577.mp3\", \"/storage/v1/object/public/pronunciation/v2/noisy-aru0-e570e577.mp3\", \"/storage/v1/object/public/pronunciation/v2/noisy-aru5-e570e577.mp3\", \"/storage/v1/object/public/pronunciation/v2/noisy-aru6-e570e577.mp3\", \"/storage/v1/object/public/pronunciation/v2/noisy-aru10-e570e577.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/noisy-aru9-e570e577.mp3\", \"/storage/v1/object/public/pronunciation/v2/noisy-aru3-e570e577.mp3\", \"/storage/v1/object/public/pronunciation/v2/noisy-aru7-e570e577.mp3\", \"/storage/v1/object/public/pronunciation/v2/noisy-aru8-e570e577.mp3\", \"/storage/v1/object/public/pronunciation/v2/noisy-aru2-e570e577.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/noisy-ljspeech-e570e577.mp3\", \"/storage/v1/object/pub