('d046f437-51ca-5fd4-878c-79833dc8d159', '916d709b-04e4-55ae-a9e0-a43b249586ee', '077e7afe-c832-5200-9411-955324bf1b49', 'a9cfa19e-2927-5645-a176-ca5f2090d69d', 'nearly', 'UK: /ˈnɪəli/ | US: /ˈnɪrli/', 'A2', 'adverb', 'gần như', 'almost completely, or coming very close to a specific state, amount, or condition.', 'The project is nearly complete.', 'Dự án gần như hoàn thành.', '{\"en\": \"The quarterly financial report is nearly complete and will be submitted by 5 PM.\", \"vi\": \"Báo cáo tài chính hàng quý gần như hoàn tất và sẽ được nộp trước 5 giờ chiều.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/nearly-ljspeech-749a9928.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/nearly-cori-749a9928.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/nearly-82efbf65.webp', '[\"almost\", \"virtually\", \"approximately\"]', '[\"exactly\", \"completely\"]', '[{\"phrase\": \"nearly double\", \"meaning\": \"gần như tăng gấp đôi\"}, {\"phrase\": \"nearly finished\", \"meaning\": \"gần như xong\"}]', '[{\"word\": \"nearby\", \"note_vi\": \"ở gần đây, gần đó (chỉ khoảng cách vị trí địa lý)\"}]', '[{\"pos\": \"adjective\", \"word\": \"near\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/nearly-cori-749a9928.mp3\", \"/storage/v1/object/public/pronunciation/v2/nearly-aru0-749a9928.mp3\", \"/storage/v1/object/public/pronunciation/v2/nearly-aru5-749a9928.mp3\", \"/storage/v1/object/public/pronunciation/v2/nearly-aru6-749a9928.mp3\", \"/storage/v1/object/public/pronunciation/v2/nearly-aru10-749a9928.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/nearly-aru9-749a9928.mp3\", \"/storage/v1/object/public/pronunciation/v2/nearly-aru3-749a9928.mp3\", \"/storage/v1/object/public/pronunciation/v2/nearly-aru7-749a9928.mp3\", \"/storage/v1/object/public/pronunciation/v2/nearly-aru8-749a9928.mp3\", \"/storage/v1/object/public/pronunciation/v2/nearly-aru2-749a9928.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object