('167043b7-5a28-5145-adf1-fc36b3f91a54', '916d709b-04e4-55ae-a9e0-a43b249586ee', '077e7afe-c832-5200-9411-955324bf1b49', 'a9cfa19e-2927-5645-a176-ca5f2090d69d', 'theater', '/ˈθɪə.tər/', 'A2', 'noun', 'tòa nhà nơi diễn ra các buổi biểu diễn kịch, nhạc kịch.', 'a building where people watch plays or movies.', 'The renovated theater will host an international film festival next month.', 'Rạp hát vừa được tân trang sẽ đăng cai tổ chức một liên hoan phim quốc tế vào tháng tới.', '{\"en\": \"The conference included a visit to a local theater for clients.\", \"vi\": \"Hội nghị bao gồm chuyến thăm một rạp hát địa phương cho khách hàng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/theater-ljspeech-d19df7d3.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/theater-cori-d19df7d3.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/theater-0f247c5f.webp', '[\"cinema\", \"playhouse\"]', NULL, '[{\"phrase\": \"movie theater\", \"meaning\": \"rạp chiếu phim\"}, {\"phrase\": \"theater ticket\", \"meaning\": \"vé rạp hát\"}]', '[{\"word\": \"theft\", \"note_vi\": \"theft là trộm cắp, dễ nhầm chính tả\"}]', '[{\"pos\": \"adjective\", \"word\": \"theatrical\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/theater-cori-d19df7d3.mp3\", \"/storage/v1/object/public/pronunciation/v2/theater-aru0-d19df7d3.mp3\", \"/storage/v1/object/public/pronunciation/v2/theater-aru5-d19df7d3.mp3\", \"/storage/v1/object/public/pronunciation/v2/theater-aru6-d19df7d3.mp3\", \"/storage/v1/object/public/pronunciation/v2/theater-aru10-d19df7d3.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/theater-aru9-d19df7d3.mp3\", \"/storage/v1/object/public/pronunciation/v2/theater-aru3-d19df7d3.mp3\", \"/storage/v1/object/public/pronunciation/v2/theater-aru7-d19df7d3.mp3\", \"/storage/v1/object/public/pronunciation/v2/theater-aru8-d19df7d3.mp3\", \"/storage/v1/object/public/pronunciation/v2/theater-aru2-d19df7d3.mp3\"]}, \"us\": {\"nu\":