('02200377-834f-5399-8851-f15e742fb8c0', '916d709b-04e4-55ae-a9e0-a43b249586ee', '089824df-2c43-5d97-b0e4-5cd1bc0078db', '250d379c-1766-51ee-b529-5df60c4170ff', 'floor', '/flɔː(r)/', 'A1', 'noun', 'Bề mặt phẳng mà bạn đi lại trong một căn phòng hoặc tòa nhà.', 'the flat surface inside a room that you walk or stand on.', 'Please don\'t drop your dirty clothes on the floor.', 'Xin đừng vứt quần áo bẩn của bạn xuống sàn nhà.', '{\"en\": \"The maintenance team will clean the office floor before the international clients arrive tomorrow.\", \"vi\": \"Đội bảo trì sẽ lau dọn sàn văn phòng trước khi khách hàng quốc tế đến vào ngày mai.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/floor-ljspeech-3684c9d3.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/floor-cori-3684c9d3.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/floor-5cdebbf3.webp', '[\"ground\", \"deck\"]', '[\"ceiling\"]', '[{\"phrase\": \"ground floor\", \"meaning\": \"tầng trệt\"}, {\"phrase\": \"wooden floor\", \"meaning\": \"sàn gỗ\"}]', '[{\"word\": \"flour\", \"note_vi\": \"bột mì, phát âm giống hệt floor nhưng viết và nghĩa khác\"}]', '[{\"pos\": \"verb\", \"word\": \"floor\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/floor-cori-3684c9d3.mp3\", \"/storage/v1/object/public/pronunciation/v2/floor-aru0-3684c9d3.mp3\", \"/storage/v1/object/public/pronunciation/v2/floor-aru5-3684c9d3.mp3\", \"/storage/v1/object/public/pronunciation/v2/floor-aru6-3684c9d3.mp3\", \"/storage/v1/object/public/pronunciation/v2/floor-aru10-3684c9d3.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/floor-aru9-3684c9d3.mp3\", \"/storage/v1/object/public/pronunciation/v2/floor-aru3-3684c9d3.mp3\", \"/storage/v1/object/public/pronunciation/v2/floor-aru7-3684c9d3.mp3\", \"/storage/v1/object/public/pronunciation/v2/floor-aru8-3684c9d3.mp3\", \"/storage/v1/object/public/pronunciation/v2/floor-aru2-3684c9d3.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/objec