('0de0930f-bd5d-5926-b99a-891a99601205', '916d709b-04e4-55ae-a9e0-a43b249586ee', '148572bc-795c-5fde-a79c-b7232a9bc500', '9ccc6733-3ead-56ce-bf37-3c62bef5135f', 'flight attendant', '/flaɪt əˈtendənt/', 'A2', 'noun', 'người phục vụ hành khách trên máy bay', 'a person who serves passengers and ensures their safety during a flight on an airplane.', 'The flight attendant demonstrated the safety procedures before takeoff.', 'Tiếp viên hàng không đã trình bày các quy trình an toàn trước khi cất cánh.', '{\"en\": \"The flight attendant asked all passengers to fasten their seatbelts before the plane began to land.\", \"vi\": \"Tiếp viên hàng không yêu cầu tất cả hành khách thắt dây an toàn trước khi máy bay hạ cánh.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/flight-attendant-ljspeech-7502033d.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/flight-attendant-cori-7502033d.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/flight-attendant-1e364a31.webp', '[\"cabin crew\", \"steward\"]', NULL, '[{\"phrase\": \"senior flight attendant\", \"meaning\": \"tiếp viên trưởng\"}, {\"phrase\": \"cabin crew\", \"meaning\": \"phi hành đoàn\"}]', '[{\"word\": \"pilot\", \"note_vi\": \"người lái máy bay, còn flight attendant phục vụ hành khách.\"}]', '[{\"pos\": \"noun\", \"word\": \"flight\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/flight-attendant-cori-7502033d.mp3\", \"/storage/v1/object/public/pronunciation/v2/flight-attendant-aru0-7502033d.mp3\", \"/storage/v1/object/public/pronunciation/v2/flight-attendant-aru5-7502033d.mp3\", \"/storage/v1/object/public/pronunciation/v2/flight-attendant-aru6-7502033d.mp3\", \"/storage/v1/object/public/pronunciation/v2/flight-attendant-aru10-7502033d.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/flight-attendant-aru9-7502033d.mp3\", \"/storage/v1/object/public/pronunciation/v2/flight-attendant-aru3-7502033d.mp3\", \"/storage/v1/object/public/pronunciatio