('f68404f4-b0ac-5b11-a506-ade82e799543', '916d709b-04e4-55ae-a9e0-a43b249586ee', '1557ad08-68b6-56cd-a988-130c6875527e', 'ae9e1ee2-ec88-5c73-a181-8e0302a3b9ad', 'paper', '', 'A1', 'noun', 'giấy và kính', 'a thin material made from wood pulp used for writing, printing, or packaging things.', 'Please separate the paper and glass for recycling.', 'Vui lòng phân loại giấy và kính để tái chế.', '{\"en\": \"Please ensure there is enough paper in the printer before printing the monthly financial reports.\", \"vi\": \"Vui lòng đảm bảo có đủ giấy trong máy in trước khi in các báo cáo tài chính hàng tháng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/paper-ljspeech-950593b1.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/paper-cori-950593b1.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/paper-3c76684e.webp', '[\"document\", \"article\", \"manuscript\"]', NULL, '[{\"phrase\": \"paper jam\", \"meaning\": \"kẹt giấy máy in\"}, {\"phrase\": \"research paper\", \"meaning\": \"bài báo/đề tài nghiên cứu\"}, {\"phrase\": \"paper trail\", \"meaning\": \"dấu vết hồ sơ giấy tờ\"}]', '[{\"word\": \"paperwork\", \"note_vi\": \"Chỉ công việc làm giấy tờ thủ tục hành chính.\"}]', '[{\"pos\": \"noun\", \"word\": \"paperwork\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/paper-cori-950593b1.mp3\", \"/storage/v1/object/public/pronunciation/v2/paper-aru0-950593b1.mp3\", \"/storage/v1/object/public/pronunciation/v2/paper-aru5-950593b1.mp3\", \"/storage/v1/object/public/pronunciation/v2/paper-aru6-950593b1.mp3\", \"/storage/v1/object/public/pronunciation/v2/paper-aru10-950593b1.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/paper-aru9-950593b1.mp3\", \"/storage/v1/object/public/pronunciation/v2/paper-aru3-950593b1.mp3\", \"/storage/v1/object/public/pronunciation/v2/paper-aru7-950593b1.mp3\", \"/storage/v1/object/public/pronunciation/v2/paper-aru8-950593b1.mp3\", \"/storage/v1/object/public/pronunciation