('450d996a-a199-50df-ae97-17daf7fac9a7', '916d709b-04e4-55ae-a9e0-a43b249586ee', '1557ad08-68b6-56cd-a988-130c6875527e', 'ae9e1ee2-ec88-5c73-a181-8e0302a3b9ad', 'diamond', '/ˈdaɪmənd/', 'B1', 'noun', 'hình tứ giác có bốn cạnh bằng nhau.', 'a flat shape with four equal straight sides that are not at right angles.', 'The pattern on the fabric was made of small diamond shapes.', 'Họa tiết trên vải được tạo thành từ những hình thoi nhỏ.', '{\"en\": \"The corporate logo features a bright blue diamond inside a red square.\", \"vi\": \"Biểu trưng của công ty có hình một hình thoi màu xanh dương tươi bên trong một hình vuông màu đỏ.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/diamond-ljspeech-f872caad.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/diamond-cori-f872caad.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/diamond-9174bd68.webp', '[\"rhombus\", \"lozenge\"]', NULL, '[{\"phrase\": \"diamond shape\", \"meaning\": \"dạng hình thoi\"}, {\"phrase\": \"in the shape of a diamond\", \"meaning\": \"theo hình thoi\"}]', '[{\"word\": \"rhombus\", \"note_vi\": \"rhombus là từ thuật ngữ toán học cho hình thoi\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/diamond-cori-f872caad.mp3\", \"/storage/v1/object/public/pronunciation/v2/diamond-aru0-f872caad.mp3\", \"/storage/v1/object/public/pronunciation/v2/diamond-aru5-f872caad.mp3\", \"/storage/v1/object/public/pronunciation/v2/diamond-aru6-f872caad.mp3\", \"/storage/v1/object/public/pronunciation/v2/diamond-aru10-f872caad.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/diamond-aru9-f872caad.mp3\", \"/storage/v1/object/public/pronunciation/v2/diamond-aru3-f872caad.mp3\", \"/storage/v1/object/public/pronunciation/v2/diamond-aru7-f872caad.mp3\", \"/storage/v1/object/public/pronunciation/v2/diamond-aru8-f872caad.mp3\", \"/storage/v1/object/public/pronunciation/v2/diamond-aru2-f872caad.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/pub