('f6566dc4-7ee4-53d8-96dc-4c32d5b3f97f', '916d709b-04e4-55ae-a9e0-a43b249586ee', '18d43d15-4d84-5145-95e5-78f1c071f1ad', '2577a2e4-59fa-59e4-877f-19fd6b0564f9', 'airplane', '/ˈeəpleɪn/', 'A2', 'noun', 'Phương tiện giao thông có cánh, dùng để bay trên không.', 'a large vehicle with wings that travels through the air to carry people or goods.', 'Our airplane will depart from Gate B12 in about an hour.', 'Máy bay của chúng tôi sẽ khởi hành từ Cổng B12 trong khoảng một giờ nữa.', '{\"en\": \"The business traveler boarded the airplane for his international flight to the company headquarters.\", \"vi\": \"Doanh nhân lên máy bay cho chuyến bay quốc tế đến trụ sở công ty.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/airplane-ljspeech-32e6c5c2.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/airplane-cori-32e6c5c2.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/airplane-f117d2b6.webp', '[\"aircraft\", \"plane\"]', NULL, '[{\"phrase\": \"board an airplane\", \"meaning\": \"lên máy bay\"}, {\"phrase\": \"airplane ticket\", \"meaning\": \"vé máy bay\"}]', NULL, NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/airplane-cori-32e6c5c2.mp3\", \"/storage/v1/object/public/pronunciation/v2/airplane-aru0-32e6c5c2.mp3\", \"/storage/v1/object/public/pronunciation/v2/airplane-aru5-32e6c5c2.mp3\", \"/storage/v1/object/public/pronunciation/v2/airplane-aru6-32e6c5c2.mp3\", \"/storage/v1/object/public/pronunciation/v2/airplane-aru10-32e6c5c2.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/airplane-aru9-32e6c5c2.mp3\", \"/storage/v1/object/public/pronunciation/v2/airplane-aru3-32e6c5c2.mp3\", \"/storage/v1/object/public/pronunciation/v2/airplane-aru7-32e6c5c2.mp3\", \"/storage/v1/object/public/pronunciation/v2/airplane-aru8-32e6c5c2.mp3\", \"/storage/v1/object/public/pronunciation/v2/airplane-aru2-32e6c5c2.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/airplane-ljspeech-32e6c5c2.m