('f4f24458-561e-5043-b568-5995874794e2', '916d709b-04e4-55ae-a9e0-a43b249586ee', '18d43d15-4d84-5145-95e5-78f1c071f1ad', '2577a2e4-59fa-59e4-877f-19fd6b0564f9', 'begin', 'UK: /bɪˈɡɪn/ | US: /bɪˈɡɪn/', 'A1', 'verb', 'bắt đầu', 'to start happening or perform the first part of an action.', 'Please begin the meeting promptly at 9 AM.', 'Vui lòng bắt đầu cuộc họp đúng 9 giờ sáng.', '{\"en\": \"The orientation session for new hires will begin promptly at nine o\'clock in the conference room.\", \"vi\": \"Buổi định hướng cho nhân viên mới sẽ bắt đầu đúng 9 giờ tại phòng họp.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/begin-ljspeech-8cbd0a74.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/begin-cori-8cbd0a74.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/begin-7122c04f.webp', '[\"start\", \"commence\", \"initiate\", \"launch\"]', '[\"finish\", \"end\", \"conclude\"]', '[{\"phrase\": \"begin promptly\", \"meaning\": \"bắt đầu đúng giờ\"}, {\"phrase\": \"begin a project\", \"meaning\": \"bắt đầu một dự án\"}, {\"phrase\": \"begin with\", \"meaning\": \"bắt đầu bằng\"}]', '[{\"word\": \"commence\", \"note_vi\": \"bắt đầu (dùng trong văn bản chính thức, trang trọng hơn)\"}]', '[{\"pos\": \"noun\", \"word\": \"beginner\"}, {\"pos\": \"noun\", \"word\": \"beginning\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/begin-cori-8cbd0a74.mp3\", \"/storage/v1/object/public/pronunciation/v2/begin-aru0-8cbd0a74.mp3\", \"/storage/v1/object/public/pronunciation/v2/begin-aru5-8cbd0a74.mp3\", \"/storage/v1/object/public/pronunciation/v2/begin-aru6-8cbd0a74.mp3\", \"/storage/v1/object/public/pronunciation/v2/begin-aru10-8cbd0a74.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/begin-aru9-8cbd0a74.mp3\", \"/storage/v1/object/public/pronunciation/v2/begin-aru3-8cbd0a74.mp3\", \"/storage/v1/object/public/pronunciation/v2/begin-aru7-8cbd0a74.mp3\", \"/storage/v1/object/public/pronunciation/v2/begin-aru8-8