('e709c4e8-688e-521f-9319-0686c50dbf3f', '916d709b-04e4-55ae-a9e0-a43b249586ee', '2200c8de-118a-5f87-8fe1-b2a69625cb17', '0276126b-af61-5d26-8f25-2ce9526881ca', 'sharp', '/ʃɑːp/', 'A2', 'adjective', 'Có cạnh hoặc đầu sắc, dễ cắt hoặc đâm.', 'having a thin edge or point that can cut or make a hole easily.', 'You should use a sharp pair of scissors to cut this cardboard box.', 'Bạn nên dùng một đôi kéo sắc để cắt chiếc hộp các-tông này.', '{\"en\": \"Please be careful when opening the package because the metal edges are very sharp.\", \"vi\": \"Xin vui lòng cẩn thận khi mở gói hàng vì các cạnh kim loại rất sắc nhọn.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/sharp-ljspeech-ca0b6293.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/sharp-cori-ca0b6293.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/sharp-6647d5c0.webp', '[\"pointed\", \"acute\"]', '[\"blunt\", \"dull\"]', '[{\"phrase\": \"sharp object\", \"meaning\": \"vật sắc nhọn\"}, {\"phrase\": \"sharp turn\", \"meaning\": \"khúc cua gấp\"}]', NULL, '[{\"pos\": \"verb\", \"word\": \"sharpen\"}, {\"pos\": \"noun\", \"word\": \"sharpness\"}, {\"pos\": \"adverb\", \"word\": \"sharply\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/sharp-cori-ca0b6293.mp3\", \"/storage/v1/object/public/pronunciation/v2/sharp-aru0-ca0b6293.mp3\", \"/storage/v1/object/public/pronunciation/v2/sharp-aru5-ca0b6293.mp3\", \"/storage/v1/object/public/pronunciation/v2/sharp-aru6-ca0b6293.mp3\", \"/storage/v1/object/public/pronunciation/v2/sharp-aru10-ca0b6293.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/sharp-aru9-ca0b6293.mp3\", \"/storage/v1/object/public/pronunciation/v2/sharp-aru3-ca0b6293.mp3\", \"/storage/v1/object/public/pronunciation/v2/sharp-aru7-ca0b6293.mp3\", \"/storage/v1/object/public/pronunciation/v2/sharp-aru8-ca0b6293.mp3\", \"/storage/v1/object/public/pronunciation/v2/sharp-aru2-ca0b6293.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/obje