('794def17-02b8-5dd4-a598-7edcdc3b80df', '916d709b-04e4-55ae-a9e0-a43b249586ee', '23f31915-9951-5e83-a44e-eee26d3c2be9', 'd5b52854-970a-5a2c-a107-7b10283f1d5f', 'add', 'UK: /æd/ | US: /æd/', 'A1', 'verb', 'thêm vào', 'to join or combine something with another to increase total amount', 'Please add your signature to the document.', 'Vui lòng thêm chữ ký của bạn vào tài liệu.', '{\"en\": \"Please add your signature to the bottom of the contract before returning it.\", \"vi\": \"Vui lòng thêm chữ ký của bạn vào cuối hợp đồng trước khi gửi lại.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/add-ljspeech-58d1bbce.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/add-cori-58d1bbce.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/add-a77fc6a8.webp', '[\"append\", \"attach\", \"include\", \"combine\"]', '[\"subtract\", \"remove\", \"deduct\"]', '[{\"phrase\": \"add value to\", \"meaning\": \"gia tăng giá trị cho\"}, {\"phrase\": \"add up to\", \"meaning\": \"cộng lại thành, tổng cộng đến\"}]', '[{\"word\": \"aid\", \"note_vi\": \"hỗ trợ, trợ giúp\"}]', '[{\"pos\": \"noun\", \"word\": \"addition\"}, {\"pos\": \"adjective\", \"word\": \"additional\"}, {\"pos\": \"adverb\", \"word\": \"additionally\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/add-cori-58d1bbce.mp3\", \"/storage/v1/object/public/pronunciation/v2/add-aru0-58d1bbce.mp3\", \"/storage/v1/object/public/pronunciation/v2/add-aru5-58d1bbce.mp3\", \"/storage/v1/object/public/pronunciation/v2/add-aru6-58d1bbce.mp3\", \"/storage/v1/object/public/pronunciation/v2/add-aru10-58d1bbce.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/add-aru9-58d1bbce.mp3\", \"/storage/v1/object/public/pronunciation/v2/add-aru3-58d1bbce.mp3\", \"/storage/v1/object/public/pronunciation/v2/add-aru7-58d1bbce.mp3\", \"/storage/v1/object/public/pronunciation/v2/add-aru8-58d1bbce.mp3\", \"/storage/v1/object/public/pronunciation/v2/add-aru2-58d1bbce.mp3\"]}, \"us