('3ae46f08-53e8-503a-bbd8-fb33c7caa641', '916d709b-04e4-55ae-a9e0-a43b249586ee', '23f31915-9951-5e83-a44e-eee26d3c2be9', 'd5b52854-970a-5a2c-a107-7b10283f1d5f', 'click', '/klɪk/', 'A2', 'verb', 'Nhấn nút chuột để chọn hoặc kích hoạt một thứ gì đó.', 'to press a button on a mouse or touchpad to choose or open something on a screen.', 'Users need to double click the icon to launch the new application.', 'Người dùng cần nhấp kép vào biểu tượng để khởi chạy ứng dụng mới.', '{\"en\": \"Click the \'Submit\' button to send your job application to our HR department.\", \"vi\": \"Nhấp vào nút \'Gửi\' để nộp đơn xin việc của bạn đến bộ phận nhân sự của chúng tôi.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/click-ljspeech-b93ec566.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/click-cori-b93ec566.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/click-e55916ab.webp', '[\"select\", \"press\"]', NULL, '[{\"phrase\": \"click on\", \"meaning\": \"nhấp vào\"}, {\"phrase\": \"double-click\", \"meaning\": \"nhấp đúp\"}, {\"phrase\": \"right-click\", \"meaning\": \"nhấp chuột phải\"}]', '[{\"word\": \"tap\", \"note_vi\": \"\'tap\' dùng cho màn hình cảm ứng, \'click\' dùng cho chuột máy tính\"}]', '[{\"pos\": \"noun\", \"word\": \"click\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/click-cori-b93ec566.mp3\", \"/storage/v1/object/public/pronunciation/v2/click-aru0-b93ec566.mp3\", \"/storage/v1/object/public/pronunciation/v2/click-aru5-b93ec566.mp3\", \"/storage/v1/object/public/pronunciation/v2/click-aru6-b93ec566.mp3\", \"/storage/v1/object/public/pronunciation/v2/click-aru10-b93ec566.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/click-aru9-b93ec566.mp3\", \"/storage/v1/object/public/pronunciation/v2/click-aru3-b93ec566.mp3\", \"/storage/v1/object/public/pronunciation/v2/click-aru7-b93ec566.mp3\", \"/storage/v1/object/public/pronunciation/v2/click-aru8-b93ec566.mp3\", \"/storage/v1/object/pu