('7f172638-3ef0-5f1e-93da-e5f890ebd970', '916d709b-04e4-55ae-a9e0-a43b249586ee', '23f31915-9951-5e83-a44e-eee26d3c2be9', 'd5b52854-970a-5a2c-a107-7b10283f1d5f', 'translation', 'UK: /trænzˈleɪʃən/ | US: /trænsˈleɪʃən/', 'B1', 'noun', 'sự biên dịch, bản dịch', 'something that has been converted from one language into another language.', 'The translation of the document is accurate.', 'Bản dịch tài liệu rất chính xác.', '{\"en\": \"Please provide an accurate English translation of the contract before signing.\", \"vi\": \"Vui lòng cung cấp bản dịch tiếng Anh chính xác của hợp đồng trước khi ký kết.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/translation-ljspeech-efd7fd7f.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/translation-cori-efd7fd7f.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/translation-d4060780.webp', '[\"rendering\", \"version\", \"transcription\", \"adaptation\"]', NULL, '[{\"phrase\": \"accurate translation\", \"meaning\": \"bản dịch chính xác\"}, {\"phrase\": \"translation service\", \"meaning\": \"dịch vụ dịch thuật\"}]', '[{\"word\": \"interpretation\", \"note_vi\": \"translation là dịch viết; interpretation là phiên dịch nói.\"}]', '[{\"pos\": \"verb\", \"word\": \"translate\"}, {\"pos\": \"noun\", \"word\": \"translator\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/translation-cori-efd7fd7f.mp3\", \"/storage/v1/object/public/pronunciation/v2/translation-aru0-efd7fd7f.mp3\", \"/storage/v1/object/public/pronunciation/v2/translation-aru5-efd7fd7f.mp3\", \"/storage/v1/object/public/pronunciation/v2/translation-aru6-efd7fd7f.mp3\", \"/storage/v1/object/public/pronunciation/v2/translation-aru10-efd7fd7f.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/translation-aru9-efd7fd7f.mp3\", \"/storage/v1/object/public/pronunciation/v2/translation-aru3-efd7fd7f.mp3\", \"/storage/v1/object/public/pronunciation/v2/translation-aru7-efd7fd7f.mp3\", \"/storage/v1/object/