('97575373-d03f-56ed-b7db-e3abfee423ac', '916d709b-04e4-55ae-a9e0-a43b249586ee', '388d7962-c46a-53ee-ade0-051bdb364cce', 'e847b580-ac01-5522-aa10-536eddaa31b7', 'timetable', 'UK: /taɪmteɪbl/ | US: /taɪm tebəl/', 'A2', 'noun', 'thời khóa biểu, lịch trình', 'a detailed plan showing the exact hours when specific activities or transport will occur', 'The new timetable will be posted online tomorrow morning.', 'Thời khóa biểu mới sẽ được đăng trực tuyến vào sáng mai.', '{\"en\": \"Passengers should check the updated train timetable on the company website.\", \"vi\": \"Hành khách nên kiểm tra lịch trình tàu hỏa đã cập nhật trên trang web của công ty.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/timetable-ljspeech-77409033.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/timetable-cori-77409033.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/timetable-0ecdb6df.webp', '[\"schedule\", \"agenda\", \"program\"]', NULL, '[{\"phrase\": \"bus timetable\", \"meaning\": \"lịch trình xe buýt\"}, {\"phrase\": \"adhere to the timetable\", \"meaning\": \"tuân thủ lịch trình\"}]', '[{\"word\": \"timepiece\", \"note_vi\": \"Timepiece là đồng hồ đeo tay/treo tường (dụng cụ đo thời gian), không phải lịch trình.\"}]', '[{\"pos\": \"verb\", \"word\": \"timetable\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/timetable-cori-77409033.mp3\", \"/storage/v1/object/public/pronunciation/v2/timetable-aru0-77409033.mp3\", \"/storage/v1/object/public/pronunciation/v2/timetable-aru5-77409033.mp3\", \"/storage/v1/object/public/pronunciation/v2/timetable-aru6-77409033.mp3\", \"/storage/v1/object/public/pronunciation/v2/timetable-aru10-77409033.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/timetable-aru9-77409033.mp3\", \"/storage/v1/object/public/pronunciation/v2/timetable-aru3-77409033.mp3\", \"/storage/v1/object/public/pronunciation/v2/timetable-aru7-77409033.mp3\", \"/storage/v1/object/public/pronunciation/v2