('e7f73a77-185d-5c19-9c5b-7144b9be06d0', '916d709b-04e4-55ae-a9e0-a43b249586ee', '3f77f443-9bf4-59ac-9b04-c5b3e28ec05a', '9dc9b6b0-1675-57d5-817f-49796b6ebc89', 'ball', '/bɔːl/', 'A1', 'noun', 'vật thể hình cầu dùng trong nhiều môn thể thao hoặc trò chơi.', 'a round object that is used in games and sports.', 'The children were kicking a red ball around in the park.', 'Bọn trẻ đang đá một quả bóng màu đỏ quanh công viên.', '{\"en\": \"The company ordered customized golf balls with their logo for the charity tournament.\", \"vi\": \"Công ty đã đặt mua những quả bóng golf tùy chỉnh có in logo của họ cho giải đấu từ thiện.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/ball-ljspeech-8bec0406.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/ball-cori-8bec0406.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/ball-131a2e20.webp', '[\"sphere\", \"globe\"]', NULL, '[{\"phrase\": \"bounce a ball\", \"meaning\": \"tâng/đập bóng\"}, {\"phrase\": \"throw a ball\", \"meaning\": \"ném bóng\"}]', '[{\"word\": \"bowl\", \"note_vi\": \"bowl là cái bát, phát âm khác ball.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/ball-cori-8bec0406.mp3\", \"/storage/v1/object/public/pronunciation/v2/ball-aru0-8bec0406.mp3\", \"/storage/v1/object/public/pronunciation/v2/ball-aru5-8bec0406.mp3\", \"/storage/v1/object/public/pronunciation/v2/ball-aru6-8bec0406.mp3\", \"/storage/v1/object/public/pronunciation/v2/ball-aru10-8bec0406.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/ball-aru9-8bec0406.mp3\", \"/storage/v1/object/public/pronunciation/v2/ball-aru3-8bec0406.mp3\", \"/storage/v1/object/public/pronunciation/v2/ball-aru7-8bec0406.mp3\", \"/storage/v1/object/public/pronunciation/v2/ball-aru8-8bec0406.mp3\", \"/storage/v1/object/public/pronunciation/v2/ball-aru2-8bec0406.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/ball-ljspeech-8bec0406.mp3\", \"/storage/v1/object/public/pro