('c3e16733-911f-5254-b377-ace79ba2f86e', '916d709b-04e4-55ae-a9e0-a43b249586ee', '67a55005-9225-58bd-8a46-d8386cd4922b', '42fb3a28-0014-5808-955d-165372ca63b2', 'nail', '/neɪl/', 'A2', 'noun', 'Lớp sừng cứng ở đầu ngón tay hoặc ngón chân.', 'the hard, flat covering that grows on the top of a human finger or toe.', 'She likes to paint her fingernails a bright pink color.', 'Cô ấy thích sơn móng tay màu hồng tươi.', '{\"en\": \"The receptionist kept her nails neat and clean for a professional appearance at work.\", \"vi\": \"Lễ tân giữ móng tay gọn gàng và sạch sẽ để có ngoại hình chuyên nghiệp tại nơi làm việc.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/nail-ljspeech-cef6dc5e.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/nail-cori-cef6dc5e.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/nail-a396794b.webp', '[\"fingernail\"]', NULL, '[{\"phrase\": \"cut one\'s nails\", \"meaning\": \"cắt móng tay\"}, {\"phrase\": \"paint one\'s nails\", \"meaning\": \"sơn móng tay\"}, {\"phrase\": \"broken nail\", \"meaning\": \"móng tay bị gãy\"}]', '[{\"word\": \"nail\", \"note_vi\": \"\'nail\' còn nghĩa là đinh (kim loại) dùng trong xây dựng, khác móng tay (noun - metal)\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/nail-cori-cef6dc5e.mp3\", \"/storage/v1/object/public/pronunciation/v2/nail-aru0-cef6dc5e.mp3\", \"/storage/v1/object/public/pronunciation/v2/nail-aru5-cef6dc5e.mp3\", \"/storage/v1/object/public/pronunciation/v2/nail-aru6-cef6dc5e.mp3\", \"/storage/v1/object/public/pronunciation/v2/nail-aru10-cef6dc5e.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/nail-aru9-cef6dc5e.mp3\", \"/storage/v1/object/public/pronunciation/v2/nail-aru3-cef6dc5e.mp3\", \"/storage/v1/object/public/pronunciation/v2/nail-aru7-cef6dc5e.mp3\", \"/storage/v1/object/public/pronunciation/v2/nail-aru8-cef6dc5e.mp3\", \"/storage/v1/object/public/pronunciation/v2/nail-aru2-cef6dc5e.mp3\"]}, \"us\": {\"