('b24f2b0e-d853-5369-a871-631013907403', '916d709b-04e4-55ae-a9e0-a43b249586ee', '745051e8-7d70-5c55-bd05-8cfc18420568', '9a1b344f-7d26-5d2f-ad06-02cf2901d58d', 'airplane', '/ˈeəpleɪn/', 'A1', 'noun', 'Phương tiện bay có cánh, dùng để chở người hoặc hàng hóa.', 'a vehicle with wings and at least one engine that flies through the air.', 'We took an airplane to travel across the country for our vacation.', 'Chúng tôi đã đi máy bay để du lịch xuyên quốc gia trong kỳ nghỉ của mình.', '{\"en\": \"The business travelers boarded the airplane to attend the international conference in Tokyo.\", \"vi\": \"Các khách doanh nhân đã lên máy bay để tham dự hội nghị quốc tế ở Tokyo.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/airplane-ljspeech-32e6c5c2.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/airplane-cori-32e6c5c2.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/airplane-f117d2b6.webp', '[\"aircraft\", \"plane\"]', NULL, '[{\"phrase\": \"board an airplane\", \"meaning\": \"lên máy bay\"}, {\"phrase\": \"airplane ticket\", \"meaning\": \"vé máy bay\"}]', '[{\"word\": \"airport\", \"note_vi\": \"sân bay, nơi máy bay cất cánh và hạ cánh\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/airplane-cori-32e6c5c2.mp3\", \"/storage/v1/object/public/pronunciation/v2/airplane-aru0-32e6c5c2.mp3\", \"/storage/v1/object/public/pronunciation/v2/airplane-aru5-32e6c5c2.mp3\", \"/storage/v1/object/public/pronunciation/v2/airplane-aru6-32e6c5c2.mp3\", \"/storage/v1/object/public/pronunciation/v2/airplane-aru10-32e6c5c2.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/airplane-aru9-32e6c5c2.mp3\", \"/storage/v1/object/public/pronunciation/v2/airplane-aru3-32e6c5c2.mp3\", \"/storage/v1/object/public/pronunciation/v2/airplane-aru7-32e6c5c2.mp3\", \"/storage/v1/object/public/pronunciation/v2/airplane-aru8-32e6c5c2.mp3\", \"/storage/v1/object/public/pronunciation/v2/airplane-aru2-32e6c5c2.mp3\"]}, \"us\"