('83310dcc-baed-50af-8668-610446a7ae80', '916d709b-04e4-55ae-a9e0-a43b249586ee', 'a2b053bd-6f18-51e4-be69-a09f76bdf405', '2c48eca4-42b0-54e7-b144-fac19c1b737b', 'grandmother', '/ˈɡrænmʌðə(r)/', 'A1', 'noun', 'Mẹ của cha hoặc mẹ của bạn.', 'the mother of a person\'s father or mother.', 'My grandmother bakes the best cookies I\'ve ever tasted.', 'Bà tôi nướng những chiếc bánh quy ngon nhất mà tôi từng nếm.', '{\"en\": \"The employee requested a day off to attend his grandmother\'s special anniversary celebration.\", \"vi\": \"Nhân viên đã yêu cầu nghỉ một ngày để tham dự lễ kỷ niệm đặc biệt của bà mình.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/grandmother-ljspeech-ea39210a.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/grandmother-cori-ea39210a.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/grandmother-387efa1f.webp', '[\"grandma\", \"granny\"]', NULL, '[{\"phrase\": \"maternal grandmother\", \"meaning\": \"bà ngoại\"}, {\"phrase\": \"paternal grandmother\", \"meaning\": \"bà nội\"}]', NULL, NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/grandmother-cori-ea39210a.mp3\", \"/storage/v1/object/public/pronunciation/v2/grandmother-aru0-ea39210a.mp3\", \"/storage/v1/object/public/pronunciation/v2/grandmother-aru5-ea39210a.mp3\", \"/storage/v1/object/public/pronunciation/v2/grandmother-aru6-ea39210a.mp3\", \"/storage/v1/object/public/pronunciation/v2/grandmother-aru10-ea39210a.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/grandmother-aru9-ea39210a.mp3\", \"/storage/v1/object/public/pronunciation/v2/grandmother-aru3-ea39210a.mp3\", \"/storage/v1/object/public/pronunciation/v2/grandmother-aru7-ea39210a.mp3\", \"/storage/v1/object/public/pronunciation/v2/grandmother-aru8-ea39210a.mp3\", \"/storage/v1/object/public/pronunciation/v2/grandmother-aru2-ea39210a.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/grandmother-ljspeech-ea39210a.mp3\", \"/storage/v1/o