('54f15064-c2a3-562c-9728-cea78cb5e02d', '916d709b-04e4-55ae-a9e0-a43b249586ee', 'ae99bef4-f684-521e-8ee0-51d3913ae609', '6c12be0b-07c5-554a-8d4e-6390d233789e', 'telephone', 'UK: /ˈtɛlɪfəʊn/ | US: /ˈtɛləˌfoʊn/', 'A1', 'noun', 'điện thoại', 'an electronic device used for transmitting vocal sounds and messages over long distances.', 'The telephone line was repaired.', 'Đường dây điện thoại đã được sửa chữa.', '{\"en\": \"Please answer the telephone promptly when a client calls the main reception desk.\", \"vi\": \"Vui lòng nghe điện thoại ngay lập tức khi khách hàng gọi đến bàn lễ tân chính.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/telephone-ljspeech-3b01d3eb.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/telephone-cori-3b01d3eb.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/telephone-1a0b2343.webp', '[\"phone\", \"landline\"]', NULL, '[{\"phrase\": \"telephone conversation\", \"meaning\": \"cuộc trò chuyện qua điện thoại\"}, {\"phrase\": \"telephone directory\", \"meaning\": \"danh bạ điện thoại\"}, {\"phrase\": \"make a telephone call\", \"meaning\": \"thực hiện cuộc gọi điện thoại\"}]', '[{\"word\": \"television\", \"note_vi\": \"tivi, thiết bị truyền hình\"}]', '[{\"pos\": \"verb\", \"word\": \"telephone\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/telephone-cori-3b01d3eb.mp3\", \"/storage/v1/object/public/pronunciation/v2/telephone-aru0-3b01d3eb.mp3\", \"/storage/v1/object/public/pronunciation/v2/telephone-aru5-3b01d3eb.mp3\", \"/storage/v1/object/public/pronunciation/v2/telephone-aru6-3b01d3eb.mp3\", \"/storage/v1/object/public/pronunciation/v2/telephone-aru10-3b01d3eb.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/telephone-aru9-3b01d3eb.mp3\", \"/storage/v1/object/public/pronunciation/v2/telephone-aru3-3b01d3eb.mp3\", \"/storage/v1/object/public/pronunciation/v2/telephone-aru7-3b01d3eb.mp3\", \"/storage/v1/object/public/pronunciation/v2/telephone-aru8-3b01d3eb