('99d9e070-4adc-5910-aa8b-00d1bc90f700', '916d709b-04e4-55ae-a9e0-a43b249586ee', 'b130cef2-89ad-506b-a87d-587e513dbc25', 'b9a16e94-51db-5b34-a5c0-68721f304c28', 'sister-in-law', '/ˈsɪstərɪnˌlɔː/', 'A2', 'noun', 'Chị hoặc em gái của vợ/chồng, hoặc vợ của anh/em trai.', 'female relative by marriage of one\'s sibling\'s spouse.', 'The company hired my sister-in-law as the new human resources manager.', 'Công ty đã nhận chị dâu của tôi làm quản lý nhân sự mới.', '{\"en\": \"His sister-in-law works in the marketing department of our firm.\", \"vi\": \"Chị/em dâu của anh ấy làm việc tại phòng marketing của công ty chúng tôi.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/sister-in-law-ljspeech-035e2214.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/sister-in-law-cori-035e2214.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/sister-in-law-a4923e2d.webp', '[\"brother\'s wife\", \"husband\'s sister\"]', NULL, '[{\"phrase\": \"my sister-in-law\", \"meaning\": \"chị/em dâu tôi\"}, {\"phrase\": \"visit sister-in-law\", \"meaning\": \"thăm chị/em dâu\"}]', '[{\"word\": \"mother-in-law\", \"note_vi\": \"mother-in-law là mẹ chồng/nợ, khác với sister-in-law.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/sister-in-law-cori-035e2214.mp3\", \"/storage/v1/object/public/pronunciation/v2/sister-in-law-aru0-035e2214.mp3\", \"/storage/v1/object/public/pronunciation/v2/sister-in-law-aru5-035e2214.mp3\", \"/storage/v1/object/public/pronunciation/v2/sister-in-law-aru6-035e2214.mp3\", \"/storage/v1/object/public/pronunciation/v2/sister-in-law-aru10-035e2214.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/sister-in-law-aru9-035e2214.mp3\", \"/storage/v1/object/public/pronunciation/v2/sister-in-law-aru3-035e2214.mp3\", \"/storage/v1/object/public/pronunciation/v2/sister-in-law-aru7-035e2214.mp3\", \"/storage/v1/object/public/pronunciation/v2/sister-in-law-aru8-035e2214.mp3\", \"/storage/v1/object/pu