('49667068-e47c-5bb9-866c-ecd0175d1f8d', '916d709b-04e4-55ae-a9e0-a43b249586ee', 'b17f39b3-f658-5533-a46c-58988bc4e5fd', '4898fbe9-4494-5439-9efb-ffc8274360de', 'paint', 'UK: /peɪnt/ | US: /peɪnt/', 'A1', 'verb', 'sơn', 'to apply liquid color or protective coating to a surface using a brush', 'He is painting the wall blue.', 'Anh ấy đang sơn bức tường màu xanh.', '{\"en\": \"Maintenance staff will paint the main office lobby over the upcoming weekend.\", \"vi\": \"Nhân viên bảo trì sẽ sơn sảnh văn phòng chính vào cuối tuần tới.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/paint-ljspeech-039f7bd6.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/paint-cori-039f7bd6.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/paint-f45c0b24.webp', '[\"coat\", \"brush\", \"color\"]', NULL, '[{\"phrase\": \"paint the interior\", \"meaning\": \"sơn nội thất\"}, {\"phrase\": \"freshly painted\", \"meaning\": \"vừa mới sơn\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"painter\"}, {\"pos\": \"noun\", \"word\": \"painting\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/paint-cori-039f7bd6.mp3\", \"/storage/v1/object/public/pronunciation/v2/paint-aru0-039f7bd6.mp3\", \"/storage/v1/object/public/pronunciation/v2/paint-aru5-039f7bd6.mp3\", \"/storage/v1/object/public/pronunciation/v2/paint-aru6-039f7bd6.mp3\", \"/storage/v1/object/public/pronunciation/v2/paint-aru10-039f7bd6.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/paint-aru9-039f7bd6.mp3\", \"/storage/v1/object/public/pronunciation/v2/paint-aru3-039f7bd6.mp3\", \"/storage/v1/object/public/pronunciation/v2/paint-aru7-039f7bd6.mp3\", \"/storage/v1/object/public/pronunciation/v2/paint-aru8-039f7bd6.mp3\", \"/storage/v1/object/public/pronunciation/v2/paint-aru2-039f7bd6.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/paint-ljspeech-039f7bd6.mp3\", \"/storage/v1/object/public/pronunciation/v2/paint-lt408-039f7bd6.mp3\", \"/st