('73ca7265-182b-5b7b-9daa-1bf730d36b44', '916d709b-04e4-55ae-a9e0-a43b249586ee', 'b17f39b3-f658-5533-a46c-58988bc4e5fd', '4898fbe9-4494-5439-9efb-ffc8274360de', 'client', '/ˈklaɪənt/', 'B1', 'noun', 'Người sử dụng dịch vụ của một công ty hoặc chuyên gia; khách hàng.', 'a person or organization that pays for professional services or advice from an expert.', 'Our law firm always prioritizes the needs of our clients.', 'Công ty luật của chúng tôi luôn ưu tiên nhu cầu của khách hàng.', '{\"en\": \"Our firm needs to prepare the quarterly financial report for our most important international client.\", \"vi\": \"Công ty chúng tôi cần chuẩn bị báo cáo tài chính hàng quý cho khách hàng quốc tế quan trọng nhất của mình.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/client-ljspeech-d2a04d71.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/client-cori-d2a04d71.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/client-fcdfdab8.webp', '[\"customer\", \"patron\"]', NULL, '[{\"phrase\": \"loyal client\", \"meaning\": \"khách hàng trung thành\"}, {\"phrase\": \"meet a client\", \"meaning\": \"gặp gỡ khách hàng\"}]', '[{\"word\": \"customer\", \"note_vi\": \"customer mua hàng hóa, client dùng dịch vụ chuyên môn.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/client-cori-d2a04d71.mp3\", \"/storage/v1/object/public/pronunciation/v2/client-aru0-d2a04d71.mp3\", \"/storage/v1/object/public/pronunciation/v2/client-aru5-d2a04d71.mp3\", \"/storage/v1/object/public/pronunciation/v2/client-aru6-d2a04d71.mp3\", \"/storage/v1/object/public/pronunciation/v2/client-aru10-d2a04d71.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/client-aru9-d2a04d71.mp3\", \"/storage/v1/object/public/pronunciation/v2/client-aru3-d2a04d71.mp3\", \"/storage/v1/object/public/pronunciation/v2/client-aru7-d2a04d71.mp3\", \"/storage/v1/object/public/pronunciation/v2/client-aru8-d2a04d71.mp3\", \"/storage/v1/object/public/pronunc