('557c92a0-109e-55a3-a293-1a224a32304c', '916d709b-04e4-55ae-a9e0-a43b249586ee', 'b59aadbe-f501-504e-95d2-1cb11c3220ef', '6687f425-d6c1-5b45-bcdb-22f80b173c8a', 'door', '/dɔː(r)/', 'A1', 'noun', 'lối ra vào một căn phòng hoặc tòa nhà.', 'a movable barrier used to enter or leave a room.', 'Remember to lock the front door securely before leaving the building.', 'Hãy nhớ khóa cửa chính cẩn thận trước khi rời khỏi tòa nhà.', '{\"en\": \"The manager knocked on the office door before entering the meeting.\", \"vi\": \"Người quản lý gõ cửa văn phòng trước khi bước vào cuộc họp.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/door-ljspeech-2680b674.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/door-cori-2680b674.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/door-8641b679.webp', NULL, NULL, '[{\"phrase\": \"front door\", \"meaning\": \"cửa trước\"}, {\"phrase\": \"door handle\", \"meaning\": \"tay nắm cửa\"}]', '[{\"word\": \"dorm\", \"note_vi\": \"dorm là ký túc xá, dễ nhầm chính tả\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/door-cori-2680b674.mp3\", \"/storage/v1/object/public/pronunciation/v2/door-aru0-2680b674.mp3\", \"/storage/v1/object/public/pronunciation/v2/door-aru5-2680b674.mp3\", \"/storage/v1/object/public/pronunciation/v2/door-aru6-2680b674.mp3\", \"/storage/v1/object/public/pronunciation/v2/door-aru10-2680b674.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/door-aru9-2680b674.mp3\", \"/storage/v1/object/public/pronunciation/v2/door-aru3-2680b674.mp3\", \"/storage/v1/object/public/pronunciation/v2/door-aru7-2680b674.mp3\", \"/storage/v1/object/public/pronunciation/v2/door-aru8-2680b674.mp3\", \"/storage/v1/object/public/pronunciation/v2/door-aru2-2680b674.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/door-ljspeech-2680b674.mp3\", \"/storage/v1/object/public/pronunciation/v2/door-lt408-2680b674.mp3\", \"/storage/v1/object/public/pronun