('69843918-14d6-5ff2-a5a2-527a1dee79af', '916d709b-04e4-55ae-a9e0-a43b249586ee', 'b8d1a942-2cce-54d8-9ec9-44aa85d15573', '2ac1672d-6e56-566b-92be-4c44c149321d', 'uniform', '/ˈjuːnɪfɔːm/', 'A2', 'noun', 'bộ quần áo giống nhau được mặc bởi một nhóm người.', 'a special set of clothes worn by members of an organization or team.', 'Flight attendants are required to wear a tidy uniform during all flights.', 'Tiếp viên hàng không được yêu cầu mặc đồng phục gọn gàng trong tất cả các chuyến bay.', '{\"en\": \"The company requires all security guards to wear their official uniform during working hours.\", \"vi\": \"Công ty yêu cầu tất cả nhân viên bảo vệ phải mặc đồng phục chính thức trong giờ làm việc.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/uniform-ljspeech-8146160c.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/uniform-cori-8146160c.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/uniform-39262441.webp', '[\"costume\", \"outfit\"]', NULL, '[{\"phrase\": \"school uniform\", \"meaning\": \"đồng phục học sinh\"}, {\"phrase\": \"wear a uniform\", \"meaning\": \"mặc đồng phục\"}]', NULL, '[{\"pos\": \"adjective\", \"word\": \"uniform\"}, {\"pos\": \"noun\", \"word\": \"uniformity\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/uniform-cori-8146160c.mp3\", \"/storage/v1/object/public/pronunciation/v2/uniform-aru0-8146160c.mp3\", \"/storage/v1/object/public/pronunciation/v2/uniform-aru5-8146160c.mp3\", \"/storage/v1/object/public/pronunciation/v2/uniform-aru6-8146160c.mp3\", \"/storage/v1/object/public/pronunciation/v2/uniform-aru10-8146160c.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/uniform-aru9-8146160c.mp3\", \"/storage/v1/object/public/pronunciation/v2/uniform-aru3-8146160c.mp3\", \"/storage/v1/object/public/pronunciation/v2/uniform-aru7-8146160c.mp3\", \"/storage/v1/object/public/pronunciation/v2/uniform-aru8-8146160c.mp3\", \"/storage/v1/object/public/pronunciation/v2/unifo