('5d79acf0-d166-5ea6-8ac8-6b649fc021ec', '916d709b-04e4-55ae-a9e0-a43b249586ee', 'bc901e6c-7790-543d-b019-5efebc1c2092', 'e64b7afc-e8ba-56d8-9b87-819076e6e998', 'urgent', 'UK: /ˈɜːdʒənt/ | US: /ˈɜːrdʒənt/', 'B1', 'adjective', 'khẩn cấp', 'requiring immediate attention, prompt action, or swift decision without any delay.', 'This matter is urgent and requires immediate attention.', 'Vấn đề này khẩn cấp và cần được giải quyết ngay lập tức.', '{\"en\": \"Please mark the email as urgent so that the IT support team will resolve the issue immediately.\", \"vi\": \"Vui lòng đánh dấu email là khẩn cấp để đội ngũ hỗ trợ CNTT xử lý sự cố ngay lập tức.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/urgent-ljspeech-8d0cdea0.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/urgent-cori-8d0cdea0.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/urgent-b038e911.webp', '[\"critical\", \"pressing\", \"imperative\", \"immediate\"]', '[\"non-urgent\", \"optional\"]', '[{\"phrase\": \"urgent matter\", \"meaning\": \"vấn đề khẩn cấp\"}, {\"phrase\": \"require urgent attention\", \"meaning\": \"yêu cầu xử lý gấp\"}]', '[{\"word\": \"important\", \"note_vi\": \"quan trọng về mặt giá trị, nhưng chưa chắc đã đòi hỏi phải làm ngay lập tức như urgent\"}]', '[{\"pos\": \"adverb\", \"word\": \"urgently\"}, {\"pos\": \"noun\", \"word\": \"urgency\"}, {\"pos\": \"verb\", \"word\": \"urge\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/urgent-cori-8d0cdea0.mp3\", \"/storage/v1/object/public/pronunciation/v2/urgent-aru0-8d0cdea0.mp3\", \"/storage/v1/object/public/pronunciation/v2/urgent-aru5-8d0cdea0.mp3\", \"/storage/v1/object/public/pronunciation/v2/urgent-aru6-8d0cdea0.mp3\", \"/storage/v1/object/public/pronunciation/v2/urgent-aru10-8d0cdea0.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/urgent-aru9-8d0cdea0.mp3\", \"/storage/v1/object/public/pronunciation/v2/urgent-aru3-8d0cdea0.mp3\", \"/storage/v1/object/pub