('5884074a-80ec-56f9-894f-d3cea655788a', '916d709b-04e4-55ae-a9e0-a43b249586ee', 'bc901e6c-7790-543d-b019-5efebc1c2092', 'e64b7afc-e8ba-56d8-9b87-819076e6e998', 'wardrobe', '/ˈwɔːdrəʊb/', 'A2', 'noun', 'tủ lớn dùng để treo và cất giữ quần áo.', 'a large cupboard for hanging and storing clothes.', 'He opened his wardrobe to choose an outfit for the party.', 'Anh ấy mở tủ quần áo để chọn một bộ trang phục cho bữa tiệc.', '{\"en\": \"The hotel room features a spacious wardrobe for guests to store their business suits.\", \"vi\": \"Phòng khách sạn có một chiếc tủ quần áo rộng rãi để khách cất những bộ vest công sở.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/wardrobe-ljspeech-149b58b2.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/wardrobe-cori-149b58b2.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/wardrobe-76a1621c.webp', '[\"closet\", \"cupboard\"]', NULL, '[{\"phrase\": \"built-in wardrobe\", \"meaning\": \"tủ quần áo âm tường\"}, {\"phrase\": \"fitted wardrobe\", \"meaning\": \"tủ quần áo thiết kế vừa vặn\"}]', '[{\"word\": \"cabinet\", \"note_vi\": \"tủ có nhiều ngăn kéo hoặc kệ, thường dùng ở bếp hoặc văn phòng.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/wardrobe-cori-149b58b2.mp3\", \"/storage/v1/object/public/pronunciation/v2/wardrobe-aru0-149b58b2.mp3\", \"/storage/v1/object/public/pronunciation/v2/wardrobe-aru5-149b58b2.mp3\", \"/storage/v1/object/public/pronunciation/v2/wardrobe-aru6-149b58b2.mp3\", \"/storage/v1/object/public/pronunciation/v2/wardrobe-aru10-149b58b2.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/wardrobe-aru9-149b58b2.mp3\", \"/storage/v1/object/public/pronunciation/v2/wardrobe-aru3-149b58b2.mp3\", \"/storage/v1/object/public/pronunciation/v2/wardrobe-aru7-149b58b2.mp3\", \"/storage/v1/object/public/pronunciation/v2/wardrobe-aru8-149b58b2.mp3\", \"/storage/v1/object/public/pronunciation/v2/wardrobe-aru2-149b58b2.mp3\"]}, \"us\": {\"nu\