('0363b291-89da-5bc5-8d93-d294c2ed8153', '916d709b-04e4-55ae-a9e0-a43b249586ee', 'c51cebb3-7389-5e58-85dd-5836f75cc0c3', '9241a4a1-fabe-5c35-9b23-3c6ba2036acb', 'lift', 'UK: /lɪft/ | US: /lɪft/', 'A2', 'verb', 'nâng lên', 'to raise something to a higher position or level from the ground.', 'Please lift the heavy boxes carefully.', 'Vui lòng nâng những chiếc hộp nặng một cách cẩn thận.', '{\"en\": \"Workers must use proper equipment when lifting heavy crates in the warehouse.\", \"vi\": \"Công nhân phải sử dụng thiết bị phù hợp khi nâng các thùng hàng nặng trong kho.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/lift-ljspeech-d9090bfd.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/lift-cori-d9090bfd.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/lift-db6ec12c.webp', '[\"raise\", \"hoist\", \"elevate\"]', '[\"lower\", \"drop\"]', '[{\"phrase\": \"lift heavy objects\", \"meaning\": \"nâng các vật nặng\"}, {\"phrase\": \"lift restrictions\", \"meaning\": \"bãi bỏ các hạn chế\"}]', '[{\"word\": \"left\", \"note_vi\": \"dạng quá khứ của \'leave\' hoặc hướng bên trái\"}]', '[{\"pos\": \"noun\", \"word\": \"lift\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/lift-cori-d9090bfd.mp3\", \"/storage/v1/object/public/pronunciation/v2/lift-aru0-d9090bfd.mp3\", \"/storage/v1/object/public/pronunciation/v2/lift-aru5-d9090bfd.mp3\", \"/storage/v1/object/public/pronunciation/v2/lift-aru6-d9090bfd.mp3\", \"/storage/v1/object/public/pronunciation/v2/lift-aru10-d9090bfd.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/lift-aru9-d9090bfd.mp3\", \"/storage/v1/object/public/pronunciation/v2/lift-aru3-d9090bfd.mp3\", \"/storage/v1/object/public/pronunciation/v2/lift-aru7-d9090bfd.mp3\", \"/storage/v1/object/public/pronunciation/v2/lift-aru8-d9090bfd.mp3\", \"/storage/v1/object/public/pronunciation/v2/lift-aru2-d9090bfd.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/lift-ljspe