('4dd8634c-ca11-5657-833c-3c4ea5953e73', '916d709b-04e4-55ae-a9e0-a43b249586ee', 'd63293ee-a627-59f6-b277-d8604c1dd47a', '3c2b1d67-9026-500f-80e7-6d2ad3b37e57', 'curved', '/kɜːvd/', 'B1', 'adjective', 'có hình dạng uốn cong, không thẳng', 'having a rounded shape that is not straight or flat.', 'The road ahead was narrow and curved sharply to the left.', 'Con đường phía trước hẹp và uốn cong gắt về bên trái.', '{\"en\": \"The architectural firm designed a modern building with a distinctive curved glass facade.\", \"vi\": \"Công ty kiến trúc đã thiết kế một tòa nhà hiện đại với mặt tiền kính cong độc đáo.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/curved-ljspeech-33d59279.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/curved-cori-33d59279.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/curved-d0b72f86.webp', '[\"bent\", \"arched\"]', '[\"straight\"]', '[{\"phrase\": \"curved line\", \"meaning\": \"đường cong\"}, {\"phrase\": \"curved surface\", \"meaning\": \"bề mặt cong\"}]', '[{\"word\": \"curly\", \"note_vi\": \"curved nói về đường/bề mặt cong; curly thường nói về tóc xoăn.\"}]', '[{\"pos\": \"noun\", \"word\": \"curve\"}, {\"pos\": \"verb\", \"word\": \"curve\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/curved-cori-33d59279.mp3\", \"/storage/v1/object/public/pronunciation/v2/curved-aru0-33d59279.mp3\", \"/storage/v1/object/public/pronunciation/v2/curved-aru5-33d59279.mp3\", \"/storage/v1/object/public/pronunciation/v2/curved-aru6-33d59279.mp3\", \"/storage/v1/object/public/pronunciation/v2/curved-aru10-33d59279.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/curved-aru9-33d59279.mp3\", \"/storage/v1/object/public/pronunciation/v2/curved-aru3-33d59279.mp3\", \"/storage/v1/object/public/pronunciation/v2/curved-aru7-33d59279.mp3\", \"/storage/v1/object/public/pronunciation/v2/curved-aru8-33d59279.mp3\", \"/storage/v1/object/public/pronunciation/v2/curved-aru2-33d59279.mp