('75d6378e-43ff-504a-85bc-3f42d5dc6372', '916d709b-04e4-55ae-a9e0-a43b249586ee', 'd67f6361-2669-5928-a283-9593777b0fea', '4f7e55f3-34b0-5684-a9c5-a779a2a2a5c0', 'juice', '/dʒuːs/', 'A1', 'noun', 'Đồ uống lỏng được chiết xuất từ trái cây hoặc rau củ.', 'the liquid that comes from fruit or vegetables when you squeeze them.', 'She enjoys a fresh glass of orange juice every morning.', 'Cô ấy thích một ly nước cam tươi mỗi sáng.', '{\"en\": \"The hotel breakfast buffet includes fresh orange juice and a variety of other healthy drinks.\", \"vi\": \"Bữa sáng tự chọn tại khách sạn bao gồm nước cam tươi và nhiều loại đồ uống lành mạnh khác.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/juice-ljspeech-07ef8791.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/juice-cori-07ef8791.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/juice-b3f7d688.webp', '[\"beverage\", \"drink\"]', NULL, '[{\"phrase\": \"orange juice\", \"meaning\": \"nước cam\"}, {\"phrase\": \"fresh juice\", \"meaning\": \"nước ép tươi\"}]', NULL, NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/juice-cori-07ef8791.mp3\", \"/storage/v1/object/public/pronunciation/v2/juice-aru0-07ef8791.mp3\", \"/storage/v1/object/public/pronunciation/v2/juice-aru5-07ef8791.mp3\", \"/storage/v1/object/public/pronunciation/v2/juice-aru6-07ef8791.mp3\", \"/storage/v1/object/public/pronunciation/v2/juice-aru10-07ef8791.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/juice-aru9-07ef8791.mp3\", \"/storage/v1/object/public/pronunciation/v2/juice-aru3-07ef8791.mp3\", \"/storage/v1/object/public/pronunciation/v2/juice-aru7-07ef8791.mp3\", \"/storage/v1/object/public/pronunciation/v2/juice-aru8-07ef8791.mp3\", \"/storage/v1/object/public/pronunciation/v2/juice-aru2-07ef8791.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/juice-ljspeech-07ef8791.mp3\", \"/storage/v1/object/public/pronunciation/v2/juice-lt408-07ef8791.mp3\", \"/sto