('629060c1-99a5-55ea-a406-bca29d0a03d5', '916d709b-04e4-55ae-a9e0-a43b249586ee', 'f9eaa297-33e4-5702-8403-3f88e6254a90', '3f657b9c-338d-553e-a09a-f6ed804ab859', 'pillow', '/ˈpɪləʊ/', 'A2', 'noun', 'Vật mềm dùng để kê đầu khi ngủ.', 'a soft object used to support your head when you are sleeping in bed.', 'I always sleep better with a soft pillow under my head.', 'Tôi luôn ngủ ngon hơn với một chiếc gối mềm dưới đầu.', '{\"en\": \"The hotel provides an extra pillow and blanket upon request at the front desk.\", \"vi\": \"Khách sạn cung cấp thêm gối và chăn theo yêu cầu tại quầy lễ tân.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/pillow-ljspeech-81cebb9e.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/pillow-cori-81cebb9e.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/pillow-cb6fc52f.webp', '[\"cushion\", \"bolster\"]', NULL, '[{\"phrase\": \"soft pillow\", \"meaning\": \"gối mềm\"}, {\"phrase\": \"pillow case\", \"meaning\": \"vỏ gối\"}]', '[{\"word\": \"cushion\", \"note_vi\": \"cushion là gối tựa sofa, pillow là gối ngủ\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/pillow-cori-81cebb9e.mp3\", \"/storage/v1/object/public/pronunciation/v2/pillow-aru0-81cebb9e.mp3\", \"/storage/v1/object/public/pronunciation/v2/pillow-aru5-81cebb9e.mp3\", \"/storage/v1/object/public/pronunciation/v2/pillow-aru6-81cebb9e.mp3\", \"/storage/v1/object/public/pronunciation/v2/pillow-aru10-81cebb9e.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/pillow-aru9-81cebb9e.mp3\", \"/storage/v1/object/public/pronunciation/v2/pillow-aru3-81cebb9e.mp3\", \"/storage/v1/object/public/pronunciation/v2/pillow-aru7-81cebb9e.mp3\", \"/storage/v1/object/public/pronunciation/v2/pillow-aru8-81cebb9e.mp3\", \"/storage/v1/object/public/pronunciation/v2/pillow-aru2-81cebb9e.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/pillow-ljspeech-81cebb9e.mp3\", \"/storage/v1/object/public/pronuncia