('cb22a9eb-a3f6-58c3-a83a-8df3f008db4a', 'bdf02489-631c-5698-862c-4839e11cf892', '2f807551-3736-51ab-9447-be04259e4e02', 'e2a045be-3588-5c44-8520-fa0339d40a6d', 'business class', '/bɪznɪs klɑːs/', 'B1', 'noun', 'Hạng ghế cao cấp hơn trên máy bay hoặc tàu hỏa.', 'a comfortable travel section on a plane or train with high service standards for professionals.', 'She usually flies business class for long international flights.', 'Cô ấy thường bay hạng thương gia cho các chuyến bay quốc tế dài.', '{\"en\": \"Corporate policy allows senior managers to travel in business class on international flights over eight hours.\", \"vi\": \"Quy định công ty cho phép quản lý cấp cao bay hạng thương gia trên các chuyến bay quốc tế dài hơn tám tiếng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/business-class-ljspeech-3cb90535.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/business-class-cori-3cb90535.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/business-class-596897b7.webp', NULL, '[\"economy class\"]', '[{\"phrase\": \"business class ticket\", \"meaning\": \"vé hạng thương gia\"}, {\"phrase\": \"business class seat\", \"meaning\": \"ghế hạng thương gia\"}]', '[{\"word\": \"economy class\", \"note_vi\": \"economy class là hạng phổ thông với giá rẻ hơn\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/business-class-cori-3cb90535.mp3\", \"/storage/v1/object/public/pronunciation/v2/business-class-aru0-3cb90535.mp3\", \"/storage/v1/object/public/pronunciation/v2/business-class-aru5-3cb90535.mp3\", \"/storage/v1/object/public/pronunciation/v2/business-class-aru6-3cb90535.mp3\", \"/storage/v1/object/public/pronunciation/v2/business-class-aru10-3cb90535.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/business-class-aru9-3cb90535.mp3\", \"/storage/v1/object/public/pronunciation/v2/business-class-aru3-3cb90535.mp3\", \"/storage/v1/object/public/pronunciation/v2/business-class-aru7-3cb90535.mp3