('306b2938-da41-55cf-a96b-5b715186897a', 'bdf02489-631c-5698-862c-4839e11cf892', '4b227664-d3b8-571d-9f36-7d735eb435ef', 'c79e9c49-eee2-55d3-95f1-e84e4a1daf43', 'javelin', '/ˈdʒævlɪn/', 'B2', 'noun', 'Cây lao dùng trong môn thể thao ném lao.', 'a long light spear that is thrown in a sporting competition.', 'The athlete trained hard for the javelin throw competition at the Olympics.', 'Vận động viên đã tập luyện chăm chỉ cho cuộc thi ném lao tại Thế vận hội.', '{\"en\": \"The sports equipment company sponsored the national javelin champion for the upcoming games.\", \"vi\": \"Công ty thiết bị thể thao đã tài trợ cho nhà vô địch ném lao quốc gia cho các trận đấu sắp tới.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/javelin-ljspeech-42fc2d95.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/javelin-cori-42fc2d95.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/javelin-e057fdcf.webp', '[\"spear\", \"lance\"]', NULL, '[{\"phrase\": \"throw the javelin\", \"meaning\": \"ném lao\"}, {\"phrase\": \"javelin thrower\", \"meaning\": \"vận động viên ném lao\"}]', '[{\"word\": \"harpoon\", \"note_vi\": \"harpoon là cây lao móc dùng để săn cá dưới nước\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/javelin-cori-42fc2d95.mp3\", \"/storage/v1/object/public/pronunciation/v2/javelin-aru0-42fc2d95.mp3\", \"/storage/v1/object/public/pronunciation/v2/javelin-aru5-42fc2d95.mp3\", \"/storage/v1/object/public/pronunciation/v2/javelin-aru6-42fc2d95.mp3\", \"/storage/v1/object/public/pronunciation/v2/javelin-aru10-42fc2d95.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/javelin-aru9-42fc2d95.mp3\", \"/storage/v1/object/public/pronunciation/v2/javelin-aru3-42fc2d95.mp3\", \"/storage/v1/object/public/pronunciation/v2/javelin-aru7-42fc2d95.mp3\", \"/storage/v1/object/public/pronunciation/v2/javelin-aru8-42fc2d95.mp3\", \"/storage/v1/object/public/pronunciation/v2/javelin-aru2-42fc2d95.mp3\"]}, \"us\"