('608cdd9a-c7cc-5018-be03-dc6026ea3551', 'bdf02489-631c-5698-862c-4839e11cf892', '4b227664-d3b8-571d-9f36-7d735eb435ef', 'c79e9c49-eee2-55d3-95f1-e84e4a1daf43', 'prompt', 'UK: /prɒmpt/ | US: /prɑmpt/', 'B2', 'adjective', 'nhanh chóng, ngay lập tức', 'done or given immediately without any unnecessary delay or waiting period', 'Prompt action is needed to resolve the customer\'s complaint.', 'Cần có hành động nhanh chóng để giải quyết khiếu nại của khách hàng.', '{\"en\": \"We appreciate your prompt response regarding the invoice payment issue.\", \"vi\": \"Chúng tôi đánh giá cao sự phản hồi nhanh chóng của bạn về vấn đề thanh toán hóa đơn.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/prompt-ljspeech-9c7e05e5.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/prompt-cori-9c7e05e5.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/prompt-6384039f.webp', '[\"immediate\", \"swift\", \"punctual\", \"rapid\"]', '[\"delayed\", \"tardy\", \"slow\"]', '[{\"phrase\": \"prompt action\", \"meaning\": \"hành động kịp thời\"}, {\"phrase\": \"prompt delivery\", \"meaning\": \"giao hàng nhanh chóng\"}]', NULL, '[{\"pos\": \"adverb\", \"word\": \"promptly\"}, {\"pos\": \"noun\", \"word\": \"promptness\"}, {\"pos\": \"verb\", \"word\": \"prompt\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/prompt-cori-9c7e05e5.mp3\", \"/storage/v1/object/public/pronunciation/v2/prompt-aru0-9c7e05e5.mp3\", \"/storage/v1/object/public/pronunciation/v2/prompt-aru5-9c7e05e5.mp3\", \"/storage/v1/object/public/pronunciation/v2/prompt-aru6-9c7e05e5.mp3\", \"/storage/v1/object/public/pronunciation/v2/prompt-aru10-9c7e05e5.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/prompt-aru9-9c7e05e5.mp3\", \"/storage/v1/object/public/pronunciation/v2/prompt-aru3-9c7e05e5.mp3\", \"/storage/v1/object/public/pronunciation/v2/prompt-aru7-9c7e05e5.mp3\", \"/storage/v1/object/public/pronunciation/v2/prompt-aru8-9c7e05e5.mp3\", \"/storage/v