('144a41c0-fca3-5862-9a08-834744ccc4b3', 'bdf02489-631c-5698-862c-4839e11cf892', '673f9700-83a1-5604-8387-7ec6441e693d', '31d189f9-9691-5e4e-90e9-a2dadc184cc8', 'father-in-law', '/ˈfɑːðərɪnˌlɔː/', 'A2', 'noun', 'Bố của vợ hoặc chồng.', 'the male parent of a person\'s husband or wife.', 'My father-in-law is a retired engineer who loves gardening.', 'Bố vợ/chồng tôi là một kỹ sư đã nghỉ hưu và rất thích làm vườn.', '{\"en\": \"The regional director invited his father-in-law to the annual corporate banquet.\", \"vi\": \"Giám đốc vùng đã mời bố vợ của ông ấy đến dự buổi tiệc thường niên của công ty.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/father-in-law-ljspeech-b2331022.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/father-in-law-cori-b2331022.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/father-in-law-43cc0d4a.webp', NULL, '[\"mother-in-law\"]', '[{\"phrase\": \"future father-in-law\", \"meaning\": \"bố vợ/bố chồng tương lai\"}]', NULL, NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/father-in-law-cori-b2331022.mp3\", \"/storage/v1/object/public/pronunciation/v2/father-in-law-aru0-b2331022.mp3\", \"/storage/v1/object/public/pronunciation/v2/father-in-law-aru5-b2331022.mp3\", \"/storage/v1/object/public/pronunciation/v2/father-in-law-aru6-b2331022.mp3\", \"/storage/v1/object/public/pronunciation/v2/father-in-law-aru10-b2331022.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/father-in-law-aru9-b2331022.mp3\", \"/storage/v1/object/public/pronunciation/v2/father-in-law-aru3-b2331022.mp3\", \"/storage/v1/object/public/pronunciation/v2/father-in-law-aru7-b2331022.mp3\", \"/storage/v1/object/public/pronunciation/v2/father-in-law-aru8-b2331022.mp3\", \"/storage/v1/object/public/pronunciation/v2/father-in-law-aru2-b2331022.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/father-in-law-ljspeech-b2331022.mp3\", \"/storage/v1/object/public/pronunciation/v2/fat