('6b8ab7e9-8c8d-5a74-9986-eba5fea47c16', 'bdf02489-631c-5698-862c-4839e11cf892', '6b0730de-5e9e-51f1-8276-f2bbfc56edc2', '1ec398cb-ffe0-5da4-bf08-05f187db6590', 'hardware', 'UK: /ˈhɑːdweə/ | US: /ˈhɑːrdwɛr/', 'B2', 'noun', 'phần cứng', 'physical components and equipment that make up an electronic system or computer.', 'We need to upgrade the computer hardware.', 'Chúng tôi cần nâng cấp phần cứng máy tính.', '{\"en\": \"The IT team is planning to upgrade the company\'s computer hardware next month.\", \"vi\": \"Đội ngũ IT đang có kế hoạch nâng cấp phần cứng máy tính của công ty vào tháng tới.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/hardware-ljspeech-608cb271.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/hardware-cori-608cb271.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/hardware-dced6fb7.webp', '[\"equipment\", \"components\", \"machinery\", \"devices\"]', '[\"software\"]', '[{\"phrase\": \"hardware store\", \"meaning\": \"cửa hàng kim khí\"}, {\"phrase\": \"hardware upgrade\", \"meaning\": \"nâng cấp phần cứng\"}]', '[{\"word\": \"software\", \"note_vi\": \"Phần mềm hoặc chương trình chạy trên máy tính.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/hardware-cori-608cb271.mp3\", \"/storage/v1/object/public/pronunciation/v2/hardware-aru0-608cb271.mp3\", \"/storage/v1/object/public/pronunciation/v2/hardware-aru5-608cb271.mp3\", \"/storage/v1/object/public/pronunciation/v2/hardware-aru6-608cb271.mp3\", \"/storage/v1/object/public/pronunciation/v2/hardware-aru10-608cb271.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/hardware-aru9-608cb271.mp3\", \"/storage/v1/object/public/pronunciation/v2/hardware-aru3-608cb271.mp3\", \"/storage/v1/object/public/pronunciation/v2/hardware-aru7-608cb271.mp3\", \"/storage/v1/object/public/pronunciation/v2/hardware-aru8-608cb271.mp3\", \"/storage/v1/object/public/pronunciation/v2/hardware-aru2-608cb271.mp3\"]}, \"us\": {\"nu\": [\