('7581a8f3-6a75-50fe-bf27-64180b997d71', 'bdf02489-631c-5698-862c-4839e11cf892', '6b0730de-5e9e-51f1-8276-f2bbfc56edc2', '1ec398cb-ffe0-5da4-bf08-05f187db6590', 'originate', 'UK: /əˈrɪdʒɪneɪt/ | US: /əˈrɪdʒɪneɪt/', 'B2', 'verb', 'bắt nguồn, khởi phát', 'To begin to exist or develop from a particular source or place.', 'The custom originated in ancient times.', 'Phong tục này bắt nguồn từ thời cổ đại.', '{\"en\": \"The proposal for the new marketing campaign originated from the junior design team.\", \"vi\": \"Đề xuất cho chiến dịch tiếp thị mới bắt nguồn từ đội ngũ thiết kế cấp dưới.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/originate-ljspeech-7b14fe90.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/originate-cori-7b14fe90.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/originate-6c9ea7a5.webp', '[\"stem\", \"derive\", \"arise\", \"spring\"]', '[\"terminate\", \"end\"]', '[{\"phrase\": \"originate from\", \"meaning\": \"bắt nguồn từ\"}, {\"phrase\": \"originate in\", \"meaning\": \"khởi phát tại/ở\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"origin\"}, {\"pos\": \"adjective\", \"word\": \"original\"}, {\"pos\": \"adverb\", \"word\": \"originally\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/originate-cori-7b14fe90.mp3\", \"/storage/v1/object/public/pronunciation/v2/originate-aru0-7b14fe90.mp3\", \"/storage/v1/object/public/pronunciation/v2/originate-aru5-7b14fe90.mp3\", \"/storage/v1/object/public/pronunciation/v2/originate-aru6-7b14fe90.mp3\", \"/storage/v1/object/public/pronunciation/v2/originate-aru10-7b14fe90.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/originate-aru9-7b14fe90.mp3\", \"/storage/v1/object/public/pronunciation/v2/originate-aru3-7b14fe90.mp3\", \"/storage/v1/object/public/pronunciation/v2/originate-aru7-7b14fe90.mp3\", \"/storage/v1/object/public/pronunciation/v2/originate-aru8-7b14fe90.mp3\", \"/storage/v1/object/public/pronunciation/v2/originate-a